BQ Tournament / Bible_Quiz_Tournament_Manager / LoadData (Turbo Pascal procedure)
procedure LoadData;
Loads tournament data from a .DAT file, initializes team records, reads team names and tournament title, handles file I/O errors by creating default teams.
Calls: 1 in this module (LoadNames)
Called by: 1 in this module (SaveData)

procedure LoadData;

  begin
    Assign(DataFile,DescName+'.DAT');
    ReSet(DataFile);
    if IOResult<>0 then begin
      FillChar(Team,SizeOf(Team),0);
      LoadNames;
      Exit;
    end;
    I:=0;
    repeat
      I:=I+1;
      Read(DataFile,Team[I]);
      Write('Loading ',I,' teams.',^M);
    until Team[I].TeamName[0]>=Chr(128);
    Writeln;
    Team[I].TeamName[0]:=Chr(Ord(Team[I].TeamName[0])-128);
    NumTeam:=I;
    Close(DataFile);
    Assign(TFile,DescName+'.DAT');
    ReSet(TFile);
    Seek(TFile,NumTeam*SizeOf(TeamRec)+1);
    TournName:='';
    repeat
      Read(TFile,AChar);
      TournName:=TournName+AChar;
    until AChar=#0;
    Close(TFile);
  end;

