BQ Tournament / Bible_Quiz_Tournament_Manager / SaveData (Turbo Pascal procedure)
procedure SaveData;
Saves team data to a .DAT file, updates tournament name, works with screen and file I/O, uses Team and TournName data structures.
Calls: 7 in this module (Browse, Edit, LoadData, LoadNames, +3 more)

procedure SaveData;

  begin
    Assign(DataFile,DescName+'.DAT');
    ReWrite(DataFile);
    Window(1,1,80,25); GotoXY(1,25); Writeln;
    Team[NumTeam].TeamName[0]:=Chr(Ord(Team[NumTeam].TeamName[0])+128);
    for I:=1 to NumTeam do begin
      Write(DataFile,Team[I]);
      Write(^M,'Saving ',I,' teams.');
    end;
    Team[NumTeam].TeamName[0]:=Chr(Ord(Team[NumTeam].TeamName[0])-128);
    Close(DataFile);
    Assign(TFile,DescName+'.DAT');
    Reset(TFile);
    Seek(TFile,NumTeam*SizeOf(TeamRec)+1);
    TournName[Length(TournName)+1]:=#0;
    for I:=1 to Length(TournName)+1 do Write(TFile,TournName[I]);
    Close(TFile);
  end;

var
  Password : string[20];
  Enter    : string[20];
  Count    : integer;

begin
  DescName:=ComLine;
  while DescName[1]=' ' do DescName:=Copy(DescName,2,Length(DescName));
  LoadData;
  TextColor(MC);
  ClrScr;
  GotoXY(1,25);
  Write('F1 BROWSE      F2 SCORES      F3 REPORT      F4 RELOAD NAMES');
  Key:=';';
  UsrOutPtr:=Ofs(UsrOutRoutine);
  CurrTeam:=1; CurrRound:=1;
  repeat
    case Key of
      ';' : begin
              GotoXY(1,25);
              TextBackground(BC);
              Write('F1 BROWSE');
              TextBackground(Black);
              Browse;
              Window(1,1,80,25);
              GotoXY(1,25);
              Write('F1 BROWSE');
            end;
      '<' : begin
              GotoXY(16,25);
              TextBackground(BC);
              Write('F2 SCORES');
              TextBackground(Black);
              Edit;
              Window(1,1,80,25);
              GotoXY(16,25);
              Write('F2 SCORES');
            end;
      '=' : begin
              GotoXY(31,25);
              TextBackground(BC);
              Write('F3 REPORT');
              TextBackground(Black);
              Report;
              Window(1,1,80,25);
              GotoXY(31,25);
              Write('F3 REPORT');
            end;
      '>' : begin
              GotoXY(46,25);
              TextBackground(BC);
              Write('F4 RELOAD NAMES');
              TextBackground(Black);
              LoadNames;
              Key:=';';
              Window(1,1,80,25);
              GotoXY(46,25);
              Write('F4 RELOAD NAMES');
            end;
      '?' : begin
              ReCalc(CurrTeam);
              Key:=';';
            end;
      'C' : begin
              ClrScr;
              SaveData;
              GotoXY(1,1);
              Write('PASSWORD TO UNLOCK : ');
              Readln(Password);
              repeat
                ClrScr;
                for Count:=1 to Length(Password) do begin
                  Read(Kbd,Enter[Count]);
                  Write('*',^G);
                end;
                Enter[0]:=Password[0];
              until Enter=Password;
              Key:=';';
              TextColor(MC);
              ClrScr;
              GotoXY(1,25);
              Write('F1 BROWSE      F2 SCORES      F3 REPORT      F4 RELOAD NAMES');
              Key:=';';
            end;
      else Key:=';';
    end;
  until Key='D';
  SaveData;
end.

BQ Tournament / Bible_Quiz_Tournament_Manager / ShowStats (Turbo Pascal procedure)
procedure ShowStats;
Displays team statistics and scores for the current round on screen, including member totals, final bell, and overall standings. Works with screen output and internal data structures.
Calls: 1 in this module (WriteScreen)
Called by: 1 in this module (WrRound)

  procedure ShowStats;

    var
      MemCount     : byte;
      StrA         : string[3];
      StrB         : string[8];

    begin
      with Team[CurrTeam] do begin
        TextBackground(Black);
        WriteScreen(Copy(TeamName,1,30),47,2,30);
        WriteScreen(Coach,57,4,20);
        Window(49,6,77,15); ClrScr;
        MemCount:=1;
        while (MemCount<=10) and (Mem[MemCount]<>'') do begin
          WriteScreen(Mem[MemCount],49,MemCount+5,26);
          Str(Round[CurrRound].Mem[MemCount].Tot:3,StrA);
          WriteScreen(StrA,73,MemCount+5,3);
          MemCount:=MemCount+1;
        end;
        Str(Round[CurrRound].FB:3,StrA);
        WriteScreen(StrA,73,16,3);
        Str(Round[CurrRound].Tot:3,StrA);
        WriteScreen(StrA,73,18,3);
        if (Round[CurrRound].Opp<>0) and (CurrRound<>0) then
          Str(Team[Round[CurrRound].Opp].Round[CurrRound].Tot:3,StrA)
          else StrA:='';
        WriteScreen(StrA,73,19,3);
        Str(W,StrA); StrB:=StrA+'-';
        Str(L,StrA); StrB:=StrB+StrA+'-';
        Str(T,StrA); StrB:=StrB+StrA;
        WriteScreen(StrB,70,20,8);
        if Round[CurrRound].Opp<>0 then
          WriteScreen(Copy(Team[Round[CurrRound].Opp].TeamName,1,30),47,23,30)
          else
            if CurrRound<>0 then WriteScreen(' BUY',47,23,30)
              else WriteScreen(' ',47,23,30);
      end;
    end;

