BQ Tournament / Bible_Quiz_Tournament_Manager / Skip (Turbo Pascal procedure)
procedure Skip;
Reads tournament data from a .BQ file, parsing team names, coaches, members, and match brackets into internal structures.

  procedure Skip;
    begin
      while (Line='') and not EOF(Desc) do Readln(Desc,Line);
    end;

  begin
    Line:='';
    Assign(Desc,DescName+'.BQ');
    ReSet(Desc);
    if IOResult<>0 then begin
      Writeln('Name file not found.');
      Halt;
    end;
    Skip;
    TournName:=Line;
    Readln(Desc,Line);
    Count1:=1;
    while Line<>':END' do begin
      Readln(Desc,Line);
      Team[Count1].TeamName:=Copy(Line,1,40);
      Readln(Desc,Line);
      Team[Count1].Coach:=Copy(Line,2,21);
      Write(^M,'Loading ',Count1,' teams.');
      Count2:=1;
      repeat
        Readln(Desc,Line);
        if Line[1]<>':' then Team[Count1].Mem[Count2]:=Copy(Line,1,20);
        Count2:=Count2+1;
      until (Line='') or (Line[1]=':');
      Count1:=Count1+1;
    end;
    Writeln;
    NumTeam:=Count1-1;
    Line:='';
    Skip;
    Count1:=1;
    while Line<>':END' do begin
      while Line<>'' do begin
        while Line[1]=' ' do Line:=Copy(Line,2,Length(Line));
        Val(Line,I,Count2);
        if Count2>0 then Line:=Copy(Line,Count2+1,Length(Line)) else Line:='';
        while Line[1]=' ' do Line:=Copy(Line,2,Length(Line));
        Val(Line,J,Count2);
        if Count2>0 then Line:=Copy(Line,Count2+1,Length(Line)) else Line:='';
        Team[I].Round[Count1].Opp:=J;
        Team[J].Round[Count1].Opp:=I;
      end;
      Writeln('Loading ',Count1,' rounds.');
      Count1:=Count1+1;
      Readln(Desc,Line);
    end;
    NumRound:=Count1-1;
    Close(Desc);
  end;


var
  TeamStand        : boolean;
  IndivStand       : boolean;
  TeamStats        : boolean;
  TournStats       : boolean;
