int Org1D::free_memory(size_t sz)
{   // tries to free up size bytes on the heap
    int count;
    long mem_freed = 0;
    for (count = 0; cells[count] != NULL; count++)
    {   delete [] cells[count];
        mem_freed += size[count];
        size[count] = 0;
    };  // for
    if (mem_freed < sz)
        return Organism::free_memory(sz-mem_freed);
    else
        return mem_freed;
