PROCEDURE Ellipse
( X,Y        : INTEGER;
  Radius     : CARDINAL; (* Radius for major axis. *)
  Aspect     : REAL );   (* X/Y aspect ratio of ellipse.
                            Use .7292 for circle on EGA. *)
(* Draws the indicated ellipse. *)
VAR
  IX, IY, IE    : INTEGER;
  AdjIX, AdjIY  : INTEGER;
BEGIN
  X:=X+INTEGER(EGALib.X1); Y:=Y+INTEGER(EGALib.Y1);
  IX:=0;
  IY:=Radius;
  IE:=0;
  WHILE IX<=IY DO
    Point(X+IX,Y+IY*35 DIV 48);
    Point(X-IX,Y+IY*35 DIV 48);
    Point(X+IX,Y-IY*35 DIV 48);
    Point(X-IX,Y-IY*35 DIV 48);
    Point(X+IY,Y+IX*35 DIV 48);
    Point(X-IY,Y+IX*35 DIV 48);
    Point(X+IY,Y-IX*35 DIV 48);
    Point(X-IY,Y-IX*35 DIV 48);
    IF IE<0 THEN
      IE:=IE+IY+IY-1;
      IY:=IY-1;
    END;
    IE:=IE-IX-IX-1;
    IX:=IX+1;
  END; (* WHILE *)
END Ellipse;

EGALib & Math / Figures / Line (Modula-2 procedure)
PROCEDURE Line ( X1,Y1,X2,Y2 : INTEGER );
Returns color at point (X,Y).
Calls: 1 in EGALib (Line), 1 in this module (Point) and 1 in FracGen (Abs)
Called by: 3 in Clock (DrawHourHand, DrawMinuteHand, DrawSecondHand), 2 in Area (FillArea, MoveArea), 1 in EGALib (Line), 1 in FracPlot (LoadSquare) and 1 in LineTrace (UpDate)

PROCEDURE Line
( X1,Y1,X2,Y2 : INTEGER );
(* Draws the specified line. *)
VAR
  dX, dY, X, Y, e : INTEGER;
  subVal, addVal  : INTEGER;
  Count           : INTEGER;
BEGIN
  dX:=ABS(X2-X1); dY:=ABS(Y2-Y1);
  IF dY<dX THEN
    IF X2<X1 THEN (* Switch coordinate pairs. *)
      X:=X1; X1:=X2; X2:=X;
      Y:=Y1; Y1:=Y2; Y2:=Y;
    END; (* IF *)
    X:=X1; Y:=Y1;
    e:=2*dY-dX;
    subVal:=2*(dY-dX); addVal:=2*dY;
    FOR Count:=1 TO dX DO
      Point(X,Y);
      IF e>0 THEN (* Change Y *)
        IF Y1<Y2 THEN INC(Y) ELSE DEC(Y) END;
        e:=e+subVal;
      ELSE
        e:=e+addVal;
      END; (* IF *)
      INC(X);
    END; (* FOR *)
  ELSE
    IF Y2<Y1 THEN (* Switch coordinate pairs. *)
      X:=X1; X1:=X2; X2:=X;
      Y:=Y1; Y1:=Y2; Y2:=Y;
    END; (* IF *)
    X:=X1; Y:=Y1;
    e:=2*dX-dY;
    subVal:=2*(dX-dY); addVal:=2*dX;
    FOR Count:=1 TO dY DO
      Point(X,Y);
      IF e>0 THEN (* Change Y *)
        IF X1<X2 THEN INC(X) ELSE DEC(X) END;
        e:=e+subVal;
      ELSE
        e:=e+addVal;
      END; (* IF *)
      INC(Y);
    END; (* FOR *)
  END; (* IF *)
END Line;

