PROCEDURE Point
( X,Y : INTEGER );
(* Plots the specified point. *)
VAR
  AtByte, AtBit : CARDINAL;
  Dummy : BYTE;
BEGIN
  IF (X<=INTEGER(EGALib.XSize)) AND (Y<=INTEGER(EGALib.YSize)) THEN
    X:=X+INTEGER(EGALib.X1); Y:=Y+INTEGER(EGALib.Y1);
    AtByte:=Y*80+(X DIV 8);
    AtBit:=X MOD 8;
    SETREG(AX,80H);
    SETREG(CX,AtBit);
    CODE(0D2H,0E8H); (* SHR AX,CL *);
    GETREG(AX,AtBit);
    OUTBYTE(3CEH,08H);
    OUTBYTE(3CFH,AtBit);
    Dummy:=Screen[AtByte];
    Screen[AtByte]:=BYTE(0FFH);
    OUTBYTE(3CEH,08H);
    OUTBYTE(3CFH,0FFH);
  END; (* IF *)
END Point;

