      WRITELN;
    END
    ELSE
    BEGIN
      DISPLAYORBITS;
      WRITELN('TOTAL NUMBER OF ACTIVE ORBITS= ',ORBITN);
      WRITELN('NUMBER OF POINTS PER ORBIT = ',POINTS);
