PROCEDURE ChangeRangeScale;
VAR
  Key : CHAR;
BEGIN
  TextMode;
  GotoXY(10, 10);
  Write('Select Range Scale:');
  GotoXY(10, 12);
  Write('1 - 5 miles    6 - 75 miles');
  GotoXY(10, 13);
  Write('2 - 10 miles   7 - 100 miles');
  GotoXY(10, 14);
  Write('3 - 25 miles   8 - 125 miles');
  GotoXY(10, 15);
  Write('4 - 35 miles   9 - 150 miles');
  GotoXY(10, 16);
  Write('5 - 50 miles   0 - 175 miles');

  REPEAT
    Read(Kbd, Key);
  UNTIL Key IN ['0'..'9'];

  CASE Key OF
    '1': CurrentRange := 0;
    '2': CurrentRange := 1;
    '3': CurrentRange := 2;
    '4': CurrentRange := 3;
    '5': CurrentRange := 4;
    '6': CurrentRange := 5;
    '7': CurrentRange := 6;
    '8': CurrentRange := 7;
    '9': CurrentRange := 8;
    '0': CurrentRange := 9;
  END;

  (* Adjust scale factor based on range *)
  ScaleFactor := 200.0 / RangeVal[CurrentRange];

  RenderMap;
END; (* ChangeRangeScale *)

(* Main Program *)
VAR
  Key : CHAR;
  Done : BOOLEAN;

BEGIN
  (* Initialize data *)
  LandmarkHIGH := 0;
  SegmentHIGH := 0;
  Done := FALSE;

  InitDisplay;

  REPEAT
    DisplayMenu;

    REPEAT
      Read(Kbd, Key);
    UNTIL Key IN [#59..#65, #27]; (* F1-F7, ESC *)

    CASE Key OF
      #59: AddLandmark;           (* F1 *)
      #60: AddSegment;            (* F2 *)
      #61: LoadMapData;           (* F3 *)
      #62: SaveMapData;           (* F4 *)
      #63: ChangeRangeScale;      (* F5 *)
      #64: BEGIN                  (* F6 - Clear *)
             LandmarkHIGH := 0;
             SegmentHIGH := 0;
             RenderMap;
           END;
      #65: RenderMap;             (* F7 *)
      #27: Done := TRUE;          (* ESC *)
    END;

  UNTIL Done;

  TextMode;
END. (* Enhanced_Map_Editor *)

