def pool_frame(frame: np.ndarray) -> np.ndarray:
    """Mean-pool a (PIC_H, PIC_W) level picture to (GRID_H, GRID_W) in [0, 1]."""
    bh, bw = PIC_H // GRID_H, PIC_W // GRID_W
