RADARPAS / Analysis / DrawMarkers (Modula-2 procedure)
PROCEDURE DrawMarkers;
Draws radar marker trails and calculates speed/direction from last two points; updates display with computed values. Works with screen graphics and trail data structure.
Calls: 3 in Graphics (GotoXY, Line, SetPlane), 1 in CDScrn (Message) and 1 in Screen (For E300 Radar Terminal: Message)

PROCEDURE DrawMarkers;
VAR
    Count  :  CARDINAL;
    dX, dY :  LONGREAL;

BEGIN
    IF LastMarker=0 THEN
        RETURN;
    END (* IF *);
    SetPlane( { 4 } );
    FOR Count := 0 TO LastMarker-1 DO
        WITH Trail[ Count ] DO
            Graph.Circle( X, Y, 3, 8 );
            IF Count > 0 THEN
                Graph.Line( X, Y, Trail[ Count-1 ].X,
                    Trail[ Count-1 ].Y, 8 );
            END (* IF *);
        END (* WITH *);
    END (* FOR *);
    IF LastMarker > 1 THEN
        dX :=  ( LONGREAL( Trail[ LastMarker-1 ].X ) -
            LONGREAL( Trail[ LastMarker-2 ].X ) )*LONGREAL( CurrRange )/256.0;
        dY :=  ( LONGREAL( Trail[ LastMarker-2 ].Y ) -
            LONGREAL( Trail[ LastMarker-1 ].Y ) )*LONGREAL( CurrRange )*
            48.0/35.0/256.0;
        Speed := MATHLIB.Sqrt( dX*dX + dY*dY );
        Dir := MATHLIB.ATan( dX/dY )*180.0/3.1415927;
        Message( " " );
        GotoXY( 310, 10 );
        WrCard( TRUNC( Speed ), 8 );
        WrCard( TRUNC( Dir+360.0 ) MOD 360, 8 );
    END (* IF *);
END DrawMarkers;

RADARPAS / Auto / AddProgram (Modula-2 procedure)
PROCEDURE AddProgram( CurrentStation : StationPtr );
LOOP
Calls: 1 in CDScrn (Message), 1 in Screen (For E300 Radar Terminal: Message), 1 in ScreenHandler (Prompt) and 1 in Selector (Select)
Called by: 1 in this module (ProgramMenu)

PROCEDURE AddProgram( CurrentStation : StationPtr );
VAR
  PromptStr : ARRAY [ 0..39 ] OF CHAR;
  Response  : ARRAY [ 0..7 ] OF CHAR;
  TempStr   : ARRAY [ 0..7 ] OF CHAR;
  OK        : BOOLEAN;
BEGIN
  IF NumofPrograms >= HIGH( Programs ) THEN
    Message( ' Program list full. ' );
    RETURN;
  END (* IF *);
  IF CurrentStation = NIL THEN
    Message( ' Must select a station.  Press F1. ' );
    RETURN;
  END (* IF *);
  INC( NumofPrograms );
  WITH Programs[NumofPrograms] DO
    Str.Slice( Station, CurrentStation^.StationName, 0,
        Str.Pos( CurrentStation^.StationName, '.' ) );
    Str.Copy( Phone, CurrentStation^.Phone );
    GetTime( NextUpdate );
    Interval := 30;
    Tilt := MAX(CARDINAL);
    Range := MAX(CARDINAL);
    Gain := MAX(CARDINAL);

    LOOP
        Response[0] := 000C;
        Prompt( ' Starting Time : ', Response );
        IF Response[0] # 000C THEN
            Str.Slice( TempStr, Response, 0, Str.Pos( Response, ':' ) );
            NextUpdate.minute := CARDINAL(Str.StrToCard(
                TempStr, 10, OK ))*60;
            IF CAP(Response[Str.Length(Response)-1]) = 'P' THEN
                INC( NextUpdate.minute, 12*60 );
                Str.Slice( Response, Response, 0, Str.Length(Response)-1 );
            ELSIF ( CAP(Response[Str.Length(Response)-1]) = 'A' ) &
                ( NextUpdate.minute DIV 60 = 12 ) THEN
                NextUpdate.minute := NextUpdate.minute MOD 60;
                Str.Slice( Response, Response, 0, Str.Length(Response)-1 );
            END (* IF *);

            Str.Slice( Response,
                Response, Str.Pos( Response, ':' )+1, 255 );
            INC( NextUpdate.minute, CARDINAL(Str.StrToCard(
                Response, 10, OK )) );
            EXIT;
        ELSE
            EXIT;
        END (* IF *);

    END (* LOOP *);

    Response[0] := 000C;
    Prompt( ' Interval  : ', Response );
    IF Response[0] # 000C THEN
        Interval := CARDINAL(Str.StrToCard( Response, 10, OK ));
    END (* IF *);

    Response[0] := 000C;
    Prompt( ' Tilt  : ', Response );
    IF Response[0] # 000C THEN

        Tilt := CARDINAL(Str.StrToCard( Response, 10, OK ));
        CASE Tilt OF
            7,8    : Tilt := 7; |
            9,10   : Tilt := 8; |
            11,12  : Tilt := 9; |
            13..15 : Tilt := 10; |
            16..20 : Tilt := 11
        ELSE
        END;  (* CASE *)

    END (* IF *);

    Response[0] := 000C;
    Prompt( ' Range : ', Response );
    IF Response[0] # 000C THEN

        Range := CARDINAL(Str.StrToCard( Response, 10, OK ));
        CASE Range DIV 10 OF
            1      : Range := 0; |
            2      : Range := 1; |
            3..5   : Range := 2; |
            6..10  : Range := 3; |
            11..20 : Range := 4
        ELSE
        END; (* CASE *)

    END (* IF *);

    Response[0] := 000C;
    Prompt( ' Gain  : ', Response );
    IF Response[0] # 000C THEN

        IF CAP(Response[0]) # 'P' THEN

            Gain := CARDINAL(Str.StrToCard( Response, 10, OK ));
            IF Gain = 0 THEN Gain := 17 END;

        ELSE

            Gain := 17;

        END (* IF *);

    END (* IF *);

  END (* WITH *);
END AddProgram;

