RADARPAS / Auto / UpdateTimes (Modula-2 procedure)
PROCEDURE UpdateTimes( VAR At : ARRAY OF BYTE );
Updates program schedule times based on current time, adjusting day and minute fields within the Programs array structure. Works with time data structures and modifies scheduled update times for radar programs.

PROCEDURE UpdateTimes( VAR At : ARRAY OF BYTE );

VAR
  Count : CARDINAL;
  CurrTime : Time;

BEGIN

  Move( ADR( At ), ADR( Programs ), 882 );
  IF NumofPrograms > 0 THEN

      GetTime( CurrTime );
      FOR Count := 1 TO NumofPrograms DO

          WITH Programs[ Count ] DO

              NextUpdate.day := CurrTime.day;
              WHILE NextUpdate.minute < CurrTime.minute DO

                  WITH NextUpdate DO

                      day := day + ( minute + Interval ) DIV 1440;
                      minute := ( minute + Interval ) MOD 1440;

                  END (* WITH *);

              END (* WHILE *);

          END (* WITH *);

      END (* FOR *);
  END (* IF *);

END UpdateTimes;

END Auto.

