RADARPAS / CheckSumTest / CalcRedundancy (Turbo Pascal procedure)
Procedure CalcRedundancy;
CodeToBitPos
Calls: 3 in this module (BitPosToCode, ChangeBit, CodeToBitPos)

Procedure CalcRedundancy;
Var
  Count  : Integer;
Begin
  Redundancy:=0;
  For Count:=0 to DataLength*8 do
    if Data[Count div 8] and (1 shl (Count mod 8))<>0 then
      Redundancy:=Redundancy xor BitPosToCode(Count);
End;

Var
  AStr        : string[255] absolute Data;
  OldRedund   : byte;
  Rate        : Integer;
  Errors      : Integer;
  NotDetected : Integer;
  Key         : Char;
  Count       : Integer;

Begin
  AStr:='ABCDEFGHIJKLMNO';
  DataLength:=Length(AStr);
  Rate:=1;
  Errors:=0;
  NotDetected:=0;
  Key:=#0;
  Randomize;
  ClrScr;
  Repeat
    WriteLn(AStr);
    CalcRedundancy;
    OldRedund:=Redundancy;
    Count:=Random(DataLength*8-1)+1;
    ChangeBit(Count);
    WriteLn('CHANGED AT ',Count);
    WriteLn(AStr);
    CalcRedundancy;
    OldRedund:=OldRedund xor Redundancy;
    Count:=CodeToBitPos(OldRedund);
    ChangeBit(Count);
    WriteLn('CORRECTED AT ',Count);
    WriteLn(AStr);
    WriteLn;
    If KeyPressed then begin
      Read(Kbd,Key);
      Case Key of
        '+' : Rate:=Rate+1;
        '-' : Rate:=Rate-1;
      End; (* Case *)
      Errors:=0;
      NotDetected:=0;
    End; (* If *)
  Until Key=#27;
End.

RADARPAS / CheckSumTest / ChangeBit (Turbo Pascal procedure)
Procedure ChangeBit(BitNumber : Integer);
In bytes
Called by: 1 in this module (CalcRedundancy)

Procedure ChangeBit(BitNumber : Integer);
Begin
  Data[BitNumber div 8]:=Data[BitNumber div 8] xor (1 shl (BitNumber mod 8));
End; (* ChangeBit *)

RADARPAS / CheckSumTest / ShowDataBinary (Turbo Pascal procedure)
Procedure ShowDataBinary;
ChangeBit

Procedure ShowDataBinary;
Begin
  WriteLn;
  For AtByte:=0 to DataLength do begin
    If AtByte mod 8 = 0 then
      Write(AtByte:4);
    If AtByte mod 2 = 0 then
      Write('  ')
    else
      Write(' ');
    For AtBit:=0 to 7 do begin
      If Data[AtByte] and (1 shl AtBit)=0 then
        Write('0')
      else
        Write('1');
    End; (* For *)
  End; (* For *)
  WriteLn;
End; (* ShowDataBinary *)

