PROCEDURE Delay(Milli : CARDINAL);
TYPE * TiltType = [ 0..11 ]; * RangeType = [ 0..4 ]; * GainType = [ 1..17 ]; * RTState = ( RTOn, RTOff, RTFault );
Calls: 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: Delay)
Called by: 5 in E300Interface (CheckMaps, GetMaps, GetParam, MakePic, +1 more), 2 in this module (GetParam, SetParam), 2 in DB (VAR Buffer: RxProcess, TxProcess), 2 in E250Term (DialRadar, RxPic), 2 in Map (CheckMap, Download), 2 in Test (Serial file transfers: RxFiles, TxFiles), 2 in TestDB (Tests the Digital Broadcast Kernel as a transient program.: CheckDOS, TermKernel), 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: Delay), 1 in Main (InterLoop), 1 in MainRx (ModemLoop), 1 in Picture (Wait), 1 in RadarRx (WritePic), 1 in RadioRx (ReceiveProc), 1 in RADIOTX (TransmitProc), 1 in rs (Return Number of recived bytes in buffer: Break), 1 in SCADB (Install2), 1 in ScrnSend (TxProcess) and 1 in Stations (Pointer to the next link in the linked list.: CallStation)

PROCEDURE Delay(Milli : CARDINAL);
(* Milli must be between 0 and 60000!!! *)
VAR
  StartTime, CurrTime : Time;
BEGIN
  GetTime(StartTime);
  LOOP
    GetTime(CurrTime);
    IF CurrTime.millisec>=StartTime.millisec THEN
      IF CurrTime.millisec-StartTime.millisec>=Milli THEN EXIT END;
    ELSIF 60000-StartTime.millisec+CurrTime.millisec>=Milli THEN
      EXIT
    END; (* IF *)
  END; (* LOOP *)
END Delay;

