RADARPAS / Control / ReadParam (Modula-2 procedure)
PROCEDURE ReadParam(VAR Tilt, Range, Gain : CARDINAL;
Reads a character from serial port, unless Milli milliseconds go by.
Calls: 2 in E300Interface (ReadParam, TimeRead), 2 in Serial (TimeRead, Write) and 1 in Graphics (Write)
Called by: 2 in this module (GetParam, SetParam) and 1 in E300Interface (ReadParam)

PROCEDURE ReadParam(VAR Tilt, Range, Gain : CARDINAL;
                    VAR TimeofPic         : Time;
                    VAR RTState           : CARDINAL);
VAR
  Buffer       : ARRAY[0..8] OF CHAR;
  Count        : CARDINAL;
  CheckSumCalc,
  CheckSumSent : CHAR;
  Hour,Minute  : CARDINAL;
BEGIN
  LOOP
    CheckSumCalc:=000c;
    TimeRead(Buffer[0],100);
    FOR Count:=1 TO 8 DO
      TimeRead(Buffer[Count],100);
      INC(CheckSumCalc,ORD(Buffer[Count]));
    END; (* FOR *)
    TimeRead(CheckSumSent,100);
    IF (Buffer[0]='Q') AND (CheckSumCalc=CheckSumSent) THEN
      Write(RadarAck);
      IF 5 IN BITSET(ORD(Buffer[2])) THEN
        Gain:=17;
      ELSE
        Gain:=ORD(Buffer[1]) DIV 16+1;
      END; (* IF *)
      Tilt:=12-(ORD(Buffer[2]) MOD 16);
      SETREG(AX,Buffer[3]);
      CODE(24H,38H); (* AND AL,38H *)
      GETREG(AX,Buffer[3]);
      CASE ORD(Buffer[3]) OF
        28H : Range:=0
|       08H : Range:=1
|       30H : Range:=2
|       00H : Range:=3
|       20H : Range:=4
        ELSE
      END; (* CASE *)
      Hour:=(ORD(Buffer[5])-48)*10+(ORD(Buffer[6])-48);
      Minute:=(ORD(Buffer[7])-48)*10+(ORD(Buffer[8])-48);
      TimeofPic.minute:=Hour*60+Minute;
      EXIT;
    ELSE
      Write(RadarNack);
    END; (* IF *)
  END; (* LOOP *)
END ReadParam;

CONST
  RadarSendParam = 'X';
  RadarTiltUp    = 002c;
  RadarTiltDown  = 005c;
  RadarRangeUp   = 003c;
  RadarRangeDown = 006c;
  RadarGainUp    = 015c;
  RadarGainDown  = 016c;

RADARPAS / Control / SetParam (Modula-2 procedure)
PROCEDURE SetParam(Tilt, Range, Gain : CARDINAL;
Sets the radar to match the parameters in CurrParam^
Calls: 3 in this module (Delay, GetParam, ReadParam), 1 in E300Interface (SetParam), 1 in Graphics (Write) and 1 in Serial (Write)
Called by: 1 in E300Interface (SetParam) and 1 in RadarVersion2point0 (Interact)

PROCEDURE SetParam(Tilt, Range, Gain : CARDINAL;
               VAR TimeofPic : Time;
               VAR RTState   : CARDINAL);
(* Sets the radar to match the parameters in CurrParam^ *)
VAR
  CurrTilt,
  CurrRange,
  CurrGain  : CARDINAL;
BEGIN
  GetParam(CurrTilt,CurrRange,CurrGain,TimeofPic,RTState);
  LOOP
    IF Tilt>CurrTilt THEN
      Write('Z'); Delay(10); Write(RadarTiltUp);
    ELSIF Tilt<CurrTilt THEN
      Write('Z'); Delay(10); Write(RadarTiltDown);
    ELSIF Range>CurrRange THEN
      Write('Z'); Delay(10); Write(RadarRangeUp);
    ELSIF Range<CurrRange THEN
      Write('Z'); Delay(10); Write(RadarRangeDown);
    ELSIF Gain>CurrGain THEN
      Write('Z'); Delay(10); Write(RadarGainUp);
    ELSIF Gain<CurrGain THEN
      Write('Z'); Delay(10); Write(RadarGainDown);
    ELSE
      EXIT;
    END; (* IF *)
    ReadParam(CurrTilt,CurrRange,CurrGain,TimeofPic,RTState);
  END; (* LOOP *)
END SetParam;

END Control.
