PROCEDURE RxProcess;
Get Rx over rs2 port
Calls: 2 in rs (Return Number of recived bytes in buffer: Receive, RxCount), 1 in Control (Delay), 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: Delay), 1 in RadioRx (Receive) and 1 in Timer (TimeOut)
Called by: 1 in this module (InstallRx)

PROCEDURE RxProcess;
(* Get Rx over rs2 port *)
BEGIN

    WHILE rs2.RxCount() > 0 DO
        rs2.Receive( RxBuf, rs2.RxCount() );
        Process.Delay( 4 );
    END (* WHILE *);
    LOOP
        (* Now receive until next sync *)
        At := 0;
        WHILE rs2.RxCount() > 0 DO
            Signal := TRUE;
            RxSize := rs2.RxCount();
            rs2.Receive( RxBuf, RxSize );
            Process.Lock;
            IF Lib.Compare( ADR( Buffer[ At ] ), ADR( RxBuf ),
                RxSize ) < RxSize THEN
                NewFile := TRUE;
                Lib.Move( ADR( RxBuf ), ADR( Buffer[ At ]), RxSize );
                At := At+RxSize;
                Size := At;
                Process.Unlock;
(*                Process.Lock;
                Lib.Fill( ADR( Buffer[ Size+1 ] ), 54000-Size, 0 );
                Process.Unlock; *)
            ELSE
(*                Lib.Move( ADR( RxBuf ), ADR( Buffer[ At ]), RxSize ); *)
                At := At+RxSize;
                Process.Unlock;
            END (* IF *);
            Process.Delay( 2 );
        END (* WHILE *);
        TimeOut := 10;
        WHILE ( rs2.RxCount()=0 ) & ( TimeOut > 0 ) DO
            Process.Delay( 1 );
            DEC( TimeOut );
        END (* WHILE *);
        IF TimeOut=0 THEN Signal:=FALSE END;
    END (* LOOP *);

END RxProcess;

