PROCEDURE RxPic;
Clear tx and rx buffer
Calls: 4 in rs (Return Number of recived bytes in buffer: Receive, RxCount, Send, TxCount), 2 in Graphics (SetFunc, SetPlane), 1 in CDScrn (Message), 1 in Control (Delay), 1 in this module (WritePic), 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: Delay), 1 in Map (Download), 1 in Picture (Download), 1 in RadioRx (Receive), 1 in Screen (For E300 Radar Terminal: Message) and 1 in TestDB (Tests the Digital Broadcast Kernel as a transient program.: Send)
Called by: 2 in E300RadarTerm (ReceivePicture, ToggleHelp), 1 in this module (DialRadar), 1 in Main (InterLoop) and 1 in MainRx (ModemLoop)

PROCEDURE RxPic;

VAR
    SentCRC  :  CARDINAL;
    Key  :  CHAR;

BEGIN

    (* Clear tx and rx buffer *)
    WHILE rs.TxCount() > 0 DO
    END (* WHILE *);
    WHILE rs.RxCount() > 0 DO

        rs.Receive( PicBuf, rs.RxCount() );

    END (* WHILE *);

    (* Initiate download *)
    rs.Send( 'X', 1 );

    (* Now download picture *)
    PicSize := 0;
    E250Scrn.FullScreen := FALSE;
    SrcAt := 0;
    DestAt := 0;
    P := 0;

    Graphics.SetFunc( Graphics.clr, 0 );
    Graphics.SetPlane( {0,1,2,3} );
    Graph.Polygon( 4, Rect(0,0,639,639),
        Rect(0,ScrnHeight,ScrnHeight,0), 0 );

    E250Scrn.DrawScale;
    E250Scrn.Message( ' Receiving picture... ' );

    WHILE ~ E250Scrn.FullScreen DO

        WHILE rs.RxCount() < BlockSize+4 DO

        END (* WHILE *);
        rs.Receive( PicSize, 2 );
        rs.Receive( PicBuf[ PicSize ], BlockSize );
        rs.Receive( SentCRC, 2 );

        IF SentCRC = CRC.CalcCRC( ADR( PicBuf[ PicSize ] ),
            BlockSize ) THEN

            rs.Send( 'A', 1 );

            E250Scrn.WritePic( PicBuf, PicSize, SrcAt, DestAt, P );

        ELSE

            Lib.Sound( 440 );
            Lib.Delay( 500 );
            Lib.NoSound;
            WHILE rs.RxCount() > 0 DO

                rs.Receive( SentCRC, 1 );

            END (* WHILE *);
            rs.Send( 'N', 1 );

        END (* IF *);

    END (* WHILE *);

END RxPic;

