procedure InitEGA;
Set 640 x 350 Hi-Res mode
Calls: 3 in Radar_Terminal (GotoXY, Initialize, WriteParams) and 1 in RADAR (WriteParams)
Called by: 1 in RADAR (InitEGA) and 1 in Radar_Terminal (Initialize)

procedure InitEGA;
  var
    I,Q            : byte;
  begin
    with Registers do begin  {Set 640 x 350 Hi-Res mode}
      AH:=$00;
      AL:=$10;
      Intr($10,Registers);
      AX:=$1130;             {Set address for character table pointer - size 14}
      BH:=$02;
      Intr($10,Registers);
      CharTab14:=Ptr(ES,BP);
      AX:=$1130;             {Set address for character table pointer - size 8}
      BH:=$03;
      Intr($10,Registers);
      CharTab8:=Ptr(ES,BP);
    end;
    for I:=0 to 15 do begin   {Initialize palette registers}
      Q:=port[$3DA];
      port[$3C0]:=I;
      port[$3C0]:=Colors[I];
    end;
    port[$3C0]:=$20;         {Enable palette registers}
    CharSize:=14;
    WriteParams(CurrentParams);
    GotoXY(1,22); Write('* H = HELP *');
    GotoXY(65,21); Write('  WLLX RADIO');
    GotoXY(65,22); Write('LAWRENCEBURG');
  end;


