RADARPAS / E300_Radar_Terminal / Rx (Turbo Pascal function)
procedure Rx(var Charac : char);
Reads next character from circular buffer, updating buffer pointer. Works with serial port receive buffer for radar data communication.

procedure Rx(var Charac : char);
  begin
    if BufBeg=BufEnd then
      Charac:=#0
    else begin
      Charac:=Buf[BufBeg];
      BufBeg:=BufBeg+1;
      if BufBeg>255 then BufBeg:=1;
    end; (* if *)
  end;

RADARPAS / E300_Radar_Terminal / RxPicLoop (Turbo Pascal procedure)
procedure RxPicLoop;
Handles reception and display of radar sweep data during RxPic mode, processing serial input and updating screen graphics with sweep lines and scale markers.
Calls: 7 in Radar_Terminal (Ask, ClearScreen, DispLine, DrawScale, +3 more), 5 in RADAR (ExecCom, GRMessage, ReadKbd, RxPicLoop, +1 more), 2 in this module (DeInit, LoadStation), 1 in Radar_Terminal_Zoom_Test (ExecCom) and 1 in RADCGA (DispLine)
Called by: 1 in this module (Sync)

procedure RxPicLoop;
  var
    Count          : integer;
  begin
    GRSize:=0;
    WriteAt:=-20000; LineAt:=-20001; PicSaveAt:=-20000;
    repeat
      if Mode=RxPic then begin
        if (RParams.Time.Hour<>CurrentParams.Time.Hour) or
          (RParams.Time.Minute<>CurrentParams.Time.Minute) then begin
          DrawScale;
          Move(RParams,CurrentParams,SIZEOF(CurrentParams));
        end;
        WriteParams(CurrentParams);
      end;
      while (Mode=RxPic) and (LineAt>WriteAt) do begin
        GRMessage('',false);
        DispLine(PicSave[WriteAt]);
        WriteAt:=WriteAt+LineSize;
      end;
      if KeyPressed then begin
        ReadKbd;
        ExecCom;
        if Key=#27 then if Ask('QUIT PROGRAM') then Key:=^Q;
      end;
    until Key=^Q;
  end;

begin
  Initialize;
  GotoXY(24,20); Write('E300 RADAR TERMINAL, ver. 1.2');
  GotoXY(30,21); Write('Copyright (C) 1986');
  GotoXY(34,22); Write('D. G. Lane');
  GotoXY(30,23); Write('All Rights Reserved');
  GotoXY(36,24); Write('SN 8705');
  ReadKbd;
  ClearScreen;
  LoadStation;
  RxPicLoop;
  DeInit;
  TextMode;
end.
