RADARPAS / E300Interface / CheckMaps (Modula-2 procedure)
PROCEDURE CheckMaps( Map1 : Map ) : BOOLEAN;
Calls a map check for the remote radar to see if a new version * of the map needs to be downloaded. If so, the new version is * downloaded and stored in Map1 and Map2, and New is returned * TRUE.
Calls: 2 in rs (Return Number of recived bytes in buffer: Receive, Send), 1 in Control (Delay), 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: Delay), 1 in Map (CheckMap), 1 in RadioRx (Receive) and 1 in TestDB (Tests the Digital Broadcast Kernel as a transient program.: Send)
Called by: 1 in Main (InterLoop) and 1 in RadarVersion2point0 (Interact)

PROCEDURE CheckMaps( Map1 : Map ) : BOOLEAN;
(* Calls a map check for the remote radar to see if a new version
 * of the map needs to be downloaded.  If so, the new version is
 * downloaded and stored in Map1 and Map2, and New is returned
 * TRUE.
 *)
VAR
  Version   : MapEntry;
  Char      : CHAR;
BEGIN
  Send('Z',1);
  Delay(10);
  Send(CheckMap,1);
  Receive(Char,1);
  Receive(Version,SIZE(Version));
  Receive(Char,1);
  Send(Ack,1);
  RETURN( Map1[0] = Version );
END CheckMaps;

RADARPAS / E300Interface / GetLine (Modula-2 procedure)
PROCEDURE GetLine ( VAR LineNum   : CARDINAL;
Initiates the radar to send the picture, but the radar might need to paint a new one first, so call PicReady() until it returns TRUE
Calls: 2 in rs (Return Number of recived bytes in buffer: Receive, Send), 1 in Convert (GetLine), 1 in this module (PicReady), 1 in Graphics (Line), 1 in RadioRx (Receive) and 1 in TestDB (Tests the Digital Broadcast Kernel as a transient program.: Send)
Called by: 2 in Main (DoAuto, InterLoop) and 1 in Convert (GetLine)

PROCEDURE GetLine
 ( VAR LineNum   : CARDINAL;
   VAR RedBitMap : ARRAY OF BYTE;
   VAR GrnBitMap : ARRAY OF BYTE );
(* Returns FALSE in PicReady until the picture is
 * being transmitted.  After that, successive calls
 * return the picture one line at a time as red and
 * green bit maps.  LineNum tells the line number,
 * ranging from 0 to 479 by 2 (since each line sent
 * is actually two screen lines).  Currently, the
 * bit maps are each 1280 pixels wide, which means
 * 160 bytes or 80 words for each bit map.
 *)
VAR
  Count        : CARDINAL;
  Buffer       : RECORD
    CASE : CARDINAL OF
      1 : LineNum : CARDINAL; |
      2 : ChrData : ARRAY [ 0..2561 ] OF CHAR; |
      3 : Data    : ARRAY [ 0..1280 ] OF CARDINAL; |
    END; (* CASE : CARDINAL *)
  END; (* RECORD *)
  CheckSumCalc,
  CheckSumSent : CHAR;
  Rep,
  AtByte, AtBit,
  Size          : CARDINAL;
  Value         : BYTE;
  Color         : BITSET;
BEGIN
  LOOP
    Count := 0;
    CheckSumCalc := 000C;
    Fill(ADR(RedBitMap),SIZE(RedBitMap),0);
    Fill(ADR(GrnBitMap),SIZE(GrnBitMap),0);
    REPEAT
      Receive(Buffer.ChrData[Count],1);
      IF ( Count = 1 ) & ( Buffer.LineNum = 1818H ) THEN
          LineNum := 478;
          RETURN;
      END (* IF *);
      INC(CheckSumCalc,ORD(Buffer.ChrData[Count]));
      INC(Count);
    UNTIL (Count>=2) & (Count MOD 2=0) & (Buffer.ChrData[Count-2]=030C);
    Receive(CheckSumSent,1);
    IF CheckSumCalc=CheckSumSent THEN
      Send(Ack,1);
      EXIT;
    END (* IF CheckSumCalc... *);
    Send(Nack,1);
  END (* LOOP *);
  WITH Buffer DO
    IF LineNum<38400 THEN
      AtByte := 0;
      AtBit := 0;
      Count := 1;
      REPEAT
        Size:=Data[Count] DIV 256 + Data[Count] MOD 32 * 256;
        Color := BITSET(Data[Count] >> 5) * BITSET(03H);
        IF Size+AtBit<=8 THEN
          Value := BYTE(0FFH) >> BYTE(8-Size) << BYTE(AtBit);
          IF 0 IN Color THEN (* 0 = Red *)
            INC(RedBitMap[AtByte],Value);
          END; (* IF 0 IN Color... *)
          IF 1 IN Color THEN (* 1 = Green *)
            INC(GrnBitMap[AtByte],Value);
          END; (* IF 1 IN Color... *)
          AtBit:=AtBit+Size;
        ELSIF Size+AtBit<=1288 THEN
          Value := BYTE(0FFH) << BYTE(AtBit);
          IF 0 IN Color THEN (* 0 = Red *)
            INC(RedBitMap[AtByte],Value);
          END; (* IF *)
          IF 1 IN Color THEN
            INC(GrnBitMap[AtByte],Value);
          END;(* IF *)
          Size := Size+AtBit-8;
          AtBit := 0;
          AtByte := AtByte+1;
          IF Size+AtBit>8 THEN
            AtBit := Size MOD 8;
            Size := Size DIV 8;
            Value := BYTE(0FFH);
            IF 0 IN Color THEN (* 0 = Red *)
              Fill(ADR(RedBitMap[AtByte]),Size,Value);
            END (* IF 0 IN Color *);
            IF 1 IN Color THEN (* 1 = Green *)
              Fill(ADR(GrnBitMap[AtByte]),Size,Value);
            END (* IF 1 IN Color *);
            AtBy

RADARPAS / E300Interface / GetMaps (Modula-2 procedure)
PROCEDURE GetMaps( VAR Map1, Map2 : Map;
Calls a map check for the remote radar to see if a new version of the map needs to be downloaded. If so, the new version is downloaded and stored in Map1 and Map2, and New is returned TRUE.
Calls: 2 in rs (Return Number of recived bytes in buffer: Receive, Send), 1 in Control (Delay), 1 in this module (ReadParam), 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: Delay), 1 in RadioRx (Receive) and 1 in TestDB (Tests the Digital Broadcast Kernel as a transient program.: Send)
Called by: 1 in Main (InterLoop)

PROCEDURE GetMaps( VAR Map1, Map2 : Map;
                   VAR Map1Len, Map2Len : CARDINAL );
(* Downloads new maps. *)
VAR

  Tilt      : TiltType;
  Range     : RangeType;
  Gain      : GainType;
  TimeofPic : Time;
  RT        : RTState;
  Char      : CHAR;

BEGIN
  Send('Z',1);
  Delay(10);
  Send(SendMap,1);
  ReadParam( Tilt, Range, Gain, TimeofPic, RT );

  Map1Len := 0;
  REPEAT

      Receive( Map1[Map1Len], 8 );
      Receive( Char, 1 );
      Delay( 10 );
      Send( Ack, 1 );
      INC( Map1Len );

  UNTIL Map1[ Map1Len-1 ].EndFlag = 0;

  REPEAT

      Receive( Map1[Map1Len], 8 );
      Receive( Char, 1 );
      Delay( 10 );
      Send( Ack, 1 );
      INC( Map1Len );

  UNTIL Map1[ Map1Len-1 ].EndFlag = 0;


  Map2Len := 0;
  REPEAT

      Receive( Map2[Map2Len], 8 );
      Receive( Char, 1 );
      Delay( 10 );
      Send( Ack, 1 );
      INC( Map2Len );

  UNTIL Map2[ Map2Len-1 ].EndFlag = 0;

  REPEAT

      Receive( Map2[Map2Len], 8 );
      Receive( Char, 1 );
      Delay( 10 );
      Send( Ack, 1 );
      INC( Map2Len );

  UNTIL Map2[ Map2Len-1 ].EndFlag = 0;

END GetMaps;


END E300Interface.


