RADARPAS / E300Interface / ReadParam (Modula-2 procedure)
PROCEDURE ReadParam ( VAR Tilt      : TiltType;
IF IO.KeyPressed() THEN RETURN; END (* IF
Calls: 1 in Control (ReadParam), 1 in this module (TimeRead), 1 in KeyDispatch (KeyPressed), 1 in rs (Return Number of recived bytes in buffer: Send) and 1 in TestDB (Tests the Digital Broadcast Kernel as a transient program.: Send)
Called by: 4 in this module (GetMaps, GetParam, MakePic, SetParam) and 1 in Control (ReadParam)

PROCEDURE ReadParam
 ( VAR Tilt      : TiltType;
   VAR Range     : RangeType;
   VAR Gain      : GainType;
   VAR TimeofPic : Time;
   VAR RT        : RTState );
VAR
  Buffer       : ARRAY[0..8] OF CHAR;
  Count        : CARDINAL;
  NumTries     : CARDINAL;
  CheckSumCalc,
  CheckSumSent : CHAR;
  Hour,Minute  : CARDINAL;
BEGIN
  GetTime( TimeofPic );
  NumTries := 0;
  LOOP
    IF IO.KeyPressed() THEN
      RETURN;
    END (* IF *);
    CheckSumCalc:=000C;
    TimeRead(Buffer[0],4000);
    IF Buffer[0] = 'Q' THEN
        FOR Count:=1 TO 8 DO
          TimeRead(Buffer[Count],4000);
          INC(CheckSumCalc,ORD(Buffer[Count]));
        END (* FOR *);
        TimeRead(CheckSumSent,4000);
        IF (* CheckSumCalc = CheckSumSent *) TRUE THEN
          Send(Ack,1);
          IF 5 IN BITSET(ORD(Buffer[2])) THEN
            Gain := 17;
          ELSE
            Gain := 1 + ORD(Buffer[1]) DIV 16;
          END (* IF *);
          Tilt:=12-(ORD(Buffer[2]) MOD 16);
          CASE CARDINAL(BITSET(Buffer[3]) * BITSET(38H)) OF
            28H : Range:=0; |
            08H : Range:=1; |
            30H : Range:=2; |
            00H : Range:=3; |
            20H : Range:=4;
            ELSE
          END (* CASE *);
          Hour:=(ORD(Buffer[5])-48)*10+(ORD(Buffer[6])-48);
          Minute:=(ORD(Buffer[7])-48)*10+(ORD(Buffer[8])-48);
          TimeofPic.minute:=Hour*60+Minute;
          IF BITSET(Buffer[3]) * {7} = {} THEN
              RT := RTOn;
          ELSIF BITSET(Buffer[3]) * {4} = {} THEN
              RT := RTOff;
          ELSE
              RT := RTFault;
          END (* IF *);
          EXIT;
        ELSIF NumTries < 20 THEN
          Send(Nack,1);
          INC( NumTries );
        ELSE
          Tilt := 255;
          Range := 255;
          Gain := 255;
          EXIT;
        END (* IF *);
    END (* IF *);
  END (* LOOP *);

(*  IO.WrStr( ' TILT : ' );
  IO.WrCard( Tilt, 1 );
  IO.WrLn;
  IO.WrStr( 'RANGE : ' );
  IO.WrCard( Range, 1 );
  IO.WrLn;
  IO.WrStr( ' GAIN : ' );
  IO.WrCard( Gain, 1 );
  IO.WrLn; *)

END ReadParam;

VAR
  CurrTilt  : TiltType;
  CurrRange : RangeType;
  CurrGain  : GainType;

RADARPAS / E300Interface / SetParam (Modula-2 procedure)
PROCEDURE SetParam (     Tilt      : TiltType;
IO.WrStr(' TILT UP...' ); IO.WrLn;
Calls: 2 in Control (Delay, SetParam), 1 in this module (ReadParam), 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: Delay), 1 in KeyDispatch (KeyPressed), 1 in rs (Return Number of recived bytes in buffer: Send) and 1 in TestDB (Tests the Digital Broadcast Kernel as a transient program.: Send)
Called by: 1 in Control (SetParam) and 1 in Main (InterLoop)

PROCEDURE SetParam
 (     Tilt      : TiltType;
       Range     : RangeType;
       Gain      : GainType;
   VAR TimeofPic : Time;
   VAR RT        : RTState );
BEGIN
  LOOP
    IF IO.KeyPressed() THEN
      RETURN;
    END (* IF *);
    IF Tilt>CurrTilt THEN
(*      IO.WrStr(' TILT UP...' );
      IO.WrLn; *)
      Send('Z',1);
      Delay(10);
      Send(TiltUp,1);
    ELSIF Tilt<CurrTilt THEN
(*      IO.WrStr(' TILT DOWN...' );
      IO.WrLn; *)
      Send('Z',1);
      Delay(10);
      Send(TiltDown,1);
    ELSIF Range>CurrRange THEN
(*      IO.WrStr(' RANGE UP...' );
      IO.WrLn; *)
      Send('Z',1);
      Delay(10);
      Send(RangeUp,1);
    ELSIF Range<CurrRange THEN
(*      IO.WrStr(' RANGE DOWN...' );
      IO.WrLn; *)
      Send('Z',1);
      Delay(10);
      Send(RangeDown,1);
    ELSIF Gain>CurrGain THEN
(*      IO.WrStr(' GAIN UP...' );
      IO.WrLn; *)
      Send('Z',1);
      Delay(10);
      Send(GainUp,1);
    ELSIF Gain<CurrGain THEN
(*      IO.WrStr(' GAIN DOWN...' );
      IO.WrLn; *)
      Send('Z',1);
      Delay(10);
      Send(GainDown,1);
    ELSE
      EXIT;
    END (* IF Tilt... *);
    ReadParam(CurrTilt,CurrRange,CurrGain,TimeofPic,RT);
    IF CurrTilt > MAX( TiltType ) THEN EXIT END;
    Delay( 100 );
  END (* LOOP *);
END SetParam;

