PROCEDURE Delay( delayM : CARDINAL);
VAR
 curTime : Time;
 startM,curM : CARDINAL;
BEGIN
 GetTime(curTime);
 startM := curTime.millisec;
 curM := startM;
 WHILE  (curM < (startM + delayM)) DO
   GetTime(curTime);
   curM := curTime.millisec;
 END;
END Delay;

