PROCEDURE DetermineComputer;
Determines computer type by reading BIOS signature at fixed memory location. Works with hardware memory structure to identify PC models from XT to AT series.
Calls: 1 in this module (Ptr)
Called by: 1 in this module (Pause)

PROCEDURE DetermineComputer;
VAR P: POINTER TO CHAR;
BEGIN
  P := Ptr(0F000H,0FFFEH);
  CASE ORD(P^) OF
    0FFH: Computer := PC;
  | 0FEH: Computer := XT;
  | 0FDH: Computer := JR;
  | 0FCH: Computer := AT;
  | 0FBH: Computer := XT2;
  | 0FAH: Computer := AT2;
  | 0F9H: Computer := CV;
  ELSE
    Computer := XT;
  END;
END DetermineComputer;

