RADARPAS / Environment / TimeDifference (Modula-2 procedure)
PROCEDURE TimeDifference( start, end: Time): REAL;
turn off lower 2 bits
Called by: 1 in this module (Pause)

PROCEDURE TimeDifference( start, end: Time): REAL;
VAR
  dif1, dif2: REAL;
BEGIN
  IF end.minute >= start.minute THEN
    dif1 := FLOAT( end.minute - start.minute );
  ELSE
    dif1 := 1440.0 (* 60*24 *) - FLOAT( start.minute - end.minute );
  END;
  IF end.millisec >= start.millisec THEN
    dif2 := FLOAT( end.millisec - start.millisec );
  ELSE
    dif2 := - FLOAT( start.millisec - end.millisec );
  END;
  RETURN dif1 * 60.0 + dif2 / 1000.0;
END TimeDifference;

RADARPAS / Environment / Tone (Modula-2 procedure)
PROCEDURE Tone( Freq,dur : CARDINAL);
Frequency := WORD(F);
Calls: 2 in Sets (Excl, Incl) and 1 in this module (Delay)
Called by: 1 in Graphics (SetHalftone), 1 in Modem (HangUp) and 1 in Stations (Pointer to the next link in the linked list.: CallStation)

PROCEDURE Tone( Freq,dur : CARDINAL);
VAR
 F,FHi,FLo : CARDINAL;
 contents : BITSET;
 Frequency : WORD;
BEGIN
 F := TRUNC( 1.193182E6 / FLOAT(Freq));
 FHi := F DIV 256;
 FLo := F MOD 256;
 (* Frequency := WORD(F); *)
 OUTBYTE(042H,CHR(FLo));    (* toneset *)
 OUTBYTE(042H,CHR(FHi));
 INBYTE(061H,contents);      (* toneon *)
 INCL(contents,0);
 INCL(contents,1);
 OUTBYTE(061H,contents);
 Delay(dur);
 INBYTE(061H,contents);  (* turn off tone *)
 EXCL(contents,0);       (* turn off lower 2 bits *);
 EXCL(contents,1);
 OUTBYTE(061H,contents);
END Tone;

