Calls: 1 in Graphics (SetPalette) and 1 in Pictures (The flags which store the state of a picture: FileName)
Called by: 1 in this module (LoadSquare)

PROCEDURE CalcSquare( VAR S : Square );
(* Body of process to calculate data for square S *)

VAR
    CountR, CountI, IterCount  :  CARDINAL;
    x  :  COMPLEX;
    ZX, ZY, ZXY  : LONGREAL;
    T  :  TimeDate.Time;
    Str  :  ARRAY [ 0..16 ] OF CHAR;

BEGIN

    TimeDate.GetTime( T );

    Graph.InitEGA;
    Graph.GraphMode;
    Graphics.SetPalette( Graphics.PaletteType( 7,
                                8, 1, 9,
                                40, 5, 45,
                                32, 4, 36,
                                48, 6, 54,
                                16, 2, 18 ) );

    WITH S DO

        IO.WrStr( FileName );
        IO.WrLngReal( C1.R, 10, 8 );
        IO.WrLngReal( C1.I, 10, 8 );
        IO.WrLn;

        FOR CountR := 0 TO SquareResolution-1 DO

            x.R := LONGREAL( CountR )/LONGREAL( SquareResolution )*
                ( C2.R-C1.R ) + C1.R;
            IO.WrChar( ASCII.cr );
            IO.WrCard( CountR, 10 );

            FOR CountI := 0 TO SquareResolution-1 DO

                x.I := LONGREAL( CountI )/LONGREAL( SquareResolution )*
                    ( C2.I-C1.I ) + C1.I;
                ZX := 0.0;
                ZY:=0.0;
                IterCount := 0;
                WHILE ( IterCount < Iterations ) & ( ZX*ZX+ZY*ZY < 8.0 ) DO
                    ZXY := 2.0 * ZX * ZY ;
                    ZX := ZX * ZX - ZY * ZY + x.R ;
                    ZY := ZXY + x.I ;
                    INC( IterCount );
                END (* WHILE *);
                Data[ CountR, CountI ] := SHORTCARD( IterCount );
                Graph.Plot( CountR+30, CountI+100, IterCount MOD 16 );
            END (* FOR *);

        END (* FOR *);
        TimeDate.TimeToString( T, Str );
        IO.WrStr( '   ' );
        IO.WrStr( Str );
        IO.WrStr( '-->' );
        TimeDate.GetTime( T );
        TimeDate.TimeToString( T, Str );
        IO.WrStr( Str );
        IO.WrStr( '    ' );
        IO.WrLn;

    END (* WITH *);

END CalcSquare;

