RADARPAS / GenTable / MakeXTable (Turbo Pascal procedure)
procedure MakeXTable;
Generates X table entries for radar sweep display using sine wave calculations. Works with global Table data structure and outputs via OutTable procedure.
Calls: 1 in this module (OutTable)
Called by: 1 in this module (MakeYTable)

procedure MakeXTable;
var
  Angle,Step : real;
  sinAngle   : real;
  Prev       : integer;
  Count,
  Count2     : integer;
begin
  Write('GENERATING X TABLE : ');
  Angle:=0.0; Step:=pi/2/Steps;
  for Count:=0 to Steps-1 do begin
    Write(Count:3,^H,^H,^H);
    sinAngle:=sin(Angle)*XRatio; Angle:=Angle+Step;
    Prev:=0;
    fillchar(Table,SizeOf(Table),0);
    for Count2:=0 to 255 do begin
      if Trunc(sinAngle*Count2)>Prev then Table:=Table+[Count2];
      Prev:=Trunc(sinAngle*Count2);
    end;
    OutTable;
  end;
  Writeln;
end;

