RADARPAS / GenTable / OutTable (Turbo Pascal procedure)
procedure OutTable;
Outputs table data as hexadecimal word values to a file, formatting 16-bit values in DW directive syntax for assembly consumption. Works with global TableData array and OutFile stream.
Calls: 1 in this module (Hex)
Called by: 2 in this module (MakeXTable, MakeYTable)

procedure OutTable;
var
  Count : integer;
begin
  Write(OutFile,'           DW ');
  for Count:=15 downto 8 do begin
    Write(OutFile,'0',Hex(TableData[Count*2+1]),Hex(TableData[Count*2]),'H');
    if Count>8 then Write(OutFile,',');
  end;
  Writeln(OutFile);
  Write(OutFile,'           DW ');
  for Count:=7 downto 0 do begin
    Write(OutFile,'0',Hex(TableData[Count*2+1]),Hex(TableData[Count*2]),'H');
    if Count>0 then Write(OutFile,',');
  end;
  Writeln(OutFile);
end;

