PROCEDURE Ellipse ( X,Y        : INTEGER;
X/Y aspect ratio of ellipse. Use .7292 for circle on EGA.
Calls: 2 in this module (Point, Ratio)
Called by: 2 in CDScrn (ClearScreen, WriteRngMks), 1 in E250DRAW (DrawMaps), 1 in MainRx (ModemLoop), 1 in ScreenHandler (WriteRngMks) and 1 in Sweep (Current radar data in use: DrawSweep)

PROCEDURE Ellipse
( X,Y        : INTEGER;
  Radius     : CARDINAL;
  Aspect     : REAL ); (* X/Y aspect ratio of ellipse.
                          Use .7292 for circle on EGA. *)
(* Draws the indicated ellipse. *)
VAR
  IX, IY, IE    : INTEGER;
  AdjIX, AdjIY  : INTEGER;
BEGIN
  X := X+WX1; Y := Y+WY1;
  IX := 0;
  IY := Radius;
  IE := 0;
  WHILE IX <= IY DO
    Point(X+IX,Y+IY*35 DIV 48);
    Point(X-IX,Y+IY*35 DIV 48);
    Point(X+IX,Y-IY*35 DIV 48);
