RADARPAS / Map / CheckMap (Modula-2 procedure)
PROCEDURE CheckMap(Map1 : ADDRESS) : BOOLEAN;
Calls a map check for the remote radar to see if a new version of the map needs to be downloaded.
Calls: 2 in Graphics (Write, WriteString), 2 in Serial (Read, Write), 1 in Control (Delay), 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: Delay) and 1 in KeyDispatch (Read)
Called by: 2 in E300Interface (CheckMaps, TimeRead)

PROCEDURE CheckMap(Map1 : ADDRESS) : BOOLEAN;
(* Calls a map check for the remote radar to see if a new version
   of the map needs to be downloaded. *)
VAR
  Buffer       : ARRAY[0..8] OF CHAR;
  Version      : POINTER TO ARRAY[1..8] OF CHAR;
  Count        : CARDINAL;
  CheckSumCalc,
  CheckSumSent : CHAR;
BEGIN
  WriteString('CHECKING GRAPHICS...');
  Write('Z'); Delay(10);
  Write(RadarCheckMap);
  LOOP
    CheckSumCalc:=000c;
    Read(Buffer[0]);
    FOR Count:=1 TO 8 DO
      Read(Buffer[Count]);
      INC(CheckSumCalc,ORD(Buffer[Count]));
    END; (* FOR *)
    Read(CheckSumSent);
    IF (Buffer[0]='G') AND (CheckSumCalc=CheckSumSent) THEN
      Write(RadarAck);
      Count:=1;
      WHILE (Version^[Count]=Buffer[Count]) AND (Count<8) DO
        INC(Count);
      END; (* WHILE *)
      IF Count=8 THEN 
        WriteString('GRAPHICS OK'); WriteLn;
      ELSE
        WriteString('GRAPHICS NOT OK'); WriteLn;
      END; (* IF *)
      RETURN (Count=8);
    ELSE
      Write(RadarNack);
    END; (* IF *)
  END; (* LOOP *)
END CheckMap;

CONST
  RadarSendMap = 000c;

