RADARPAS / Map / Download (Modula-2 procedure)
PROCEDURE Download(Map1, Map2 : ADDRESS);
Calls a map check for the remote radar to see if a new version of the map needs to be downloaded.
Calls: 2 in Graphics (Write, WriteString), 2 in Serial (Read, Write), 1 in Control (Delay), 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: Delay), 1 in KeyDispatch (Read) and 1 in Picture (Download)
Called by: 1 in E250Term (RxPic) and 1 in Picture (Download)

PROCEDURE Download(Map1, Map2 : ADDRESS);
(* Downloads the radar's two maps into the two buffers indicated. *)
VAR
  Buffer       : POINTER TO ARRAY[0..8] OF CHAR;
  MapCount     : CARDINAL;
  Count        : CARDINAL;
  CheckSumCalc,
  CheckSumSent : CHAR;
  TempAdr      : ADDRESS;
  Tilt, Range, Gain : CARDINAL;
  TimeofPic    : Time;
  RTState      : CARDINAL;
BEGIN
  WriteString('DOWNLOADING MAPS...');
  Write('Z'); Delay(15);
  Write(RadarSendMap);
  FOR Count:=0 TO 9 DO
    Read(CheckSumSent);
    WriteString(CheckSumSent);
  END; (* FOR *)
  WriteCard(1,5);
  Buffer:=Map1; MapCount:=1;
  LOOP
    CheckSumCalc:=000c;
    FOR Count:=0 TO 7 DO
      Read(Buffer^[Count]);
      INC(CheckSumCalc,ORD(Buffer^[Count]));
    END; (* FOR *)
    Read(CheckSumSent);
    Delay(10); WriteString('*');
    IF (* CheckSumCalc=CheckSumSent *) TRUE THEN
      Write(RadarAck);
      TempAdr:=Buffer;
      INC(TempAdr,8);
      Buffer:=TempAdr;
      IF (Buffer^[0]=000c) AND (Buffer^[1]=000c) THEN
        INC(MapCount);
        WriteCard(MapCount,4);
        IF MapCount=3 THEN
          Buffer:=Map2;
        ELSIF MapCount=5 THEN
          WriteString('DONE.'); WriteLn;
          EXIT;
        END; (* IF *)
      END; (* IF *)
    ELSE
      Write(RadarNack);
    END; (* IF *)
  END; (* LOOP *)
END Download;

