RADARPAS / MenuUtility / DoMenu (Modula-2 procedure)
PROCEDURE DoMenu ( ForMenu : Menu;     (* List of items to use *)
Enunciate the obvious Note that the keystroke to exit has a NIL value for WhenSelect
Calls: 1 in Graphics (WriteString) and 1 in this module (HiliteMenu)

PROCEDURE DoMenu
( ForMenu : Menu;     (* List of items to use *)
  Bar     : BOOLEAN;  (* True to indicate bar-type menu *)
  Width   : CARDINAL; (* Width of menu window 
                         Set to 0 to have set to minimum *)
  X,Y     : CARDINAL; (* X,Y position of menu window
                         Set to 0 to have set to center *) 
);
VAR
  Count, Max, 
  CurrPos     : CARDINAL;
  Key         : CHAR;
  Escape      : BOOLEAN;
BEGIN
  IF Bar THEN
    Max:=0;
    FOR Count:=1 TO HIGH(ForMenu) DO
      Max:=Max+Length(ForMenu[Count].Name)+2;
    END; (* FOR *)
    IF Width=0 THEN Width:=Max;
    IF X=0 THEN X:=(80-Width) DIV 2;
    Frame(X*8,Y*14,(X+Width)*8,(Y+1)*8);
    CurrPos:=0;
    FOR Count:=1 TO HIGH(ForMenu) DO
      ForMenu[Count].Pos:=CurrPos;
      WriteString(' ');
      WriteString(ForMenu[Count].Name);
      WriteString(' ');
      CurrPos:=CurrPos+Length(ForMenu[Count].Name)+2;
    END; (* FOR *)
  ELSE
    IF Width=0 THEN
      FOR Count:=1 TO HIGH(ForMenu) DO
        IF Length(ForMenu[Count]).Name>Max THEN 
          Max:=Length(ForMenu[Count].Name);
        END; (* IF *)
      END; (* FOR *)
    END (* IF *);
    IF X=0 THEN X:=(ScreenWidth-Width) DIV 2;
    IF Y=0 THEN Y:=(ScreenHeight-HIGH(ForMenu)+1) DIV 2;
    Frame(X*8,Y*14,(X+Width-1)*8,(Y+HIGH(ForMenu))*14);
  END; (* IF *)
  LOOP
    ExtendRead(Key,Escape);
    Count:=0;
    WHILE (Key<>ForMenu[Count].Key) AND (Escape<>ForMenu[Count].Escape)
        AND (Count<=HIGH(ForMenu)) DO
      INC(Count);
    END; (* WHILE *)
    IF Count<=HIGH(ForMenu) THEN
      WITH ForMenu[Count] DO
        OldX:=X; OldY:=Y; 
        OldCount:=Count; OldWidth:=Width;
        HiliteMenu;
        IF WhenSelect<>NIL THEN
          WhenSelect;
        ELSE
          EXIT;
        END; (* IF *)
        HiliteMenu;
      END; (* WIDTH *)
    END; (* IF *)
  END; (* LOOP *)
END DoMenu;

VAR
  ToggleOn, OldX, OldY, OldCount, OldWidth : CARDINAL;

RADARPAS / MenuUtility / HiliteMenu (Modula-2 procedure)
PROCEDURE HiliteMenu;
LOOP
Called by: 1 in this module (DoMenu)

PROCEDURE HiliteMenu;
BEGIN
  IF OldWidth>0 THEN
    FillAreaFunc(X*8,(Y+Count)*14,(X+Width)*8,(Y+Count)*14+13,255,xor);
    IF ToggleOn THEN 
      OldWidth:=0;
      ToggleOn:=FALSE;
    ELSE 
      ToggleOn:=TRUE;
    END; (* IF *)
  END; (* IF *)
END HiliteMenu;

RADARPAS / Modem / Call (Modula-2 procedure)
PROCEDURE Call(PhoneNum : ARRAY OF CHAR);
Dials the number Number (which may contain Hayes dial modifiers) and sets Result accordingly.
Calls: 2 in E300RadarTerm (Offline, Online), 2 in Serial (Read, Write), 1 in Graphics (Write) and 1 in KeyDispatch (Read)
Called by: 3 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: Cls, GotoXY, Locate), 2 in E300RadarTerm (Offline, ToggleHelp), 1 in Auto (ProgramMenu), 1 in E250Term (DialRadar), 1 in E300Interface (AbortPic), 1 in KeyDispatch (Peek), 1 in Picture (Wait), 1 in RadarTerminal (Interactive), 1 in RadarVersion2point0 (Interact), 1 in Serial (WaitBreak) and 1 in Stations (Pointer to the next link in the linked list.: CallStation)

PROCEDURE Call(PhoneNum : ARRAY OF CHAR);
VAR
  Char1,Char2 : CHAR;
BEGIN
  REPEAT
    RS232Code.BusyRead(Char1,done);
  UNTIL done=FALSE;
  Write('A'); Write('T');
  Write('T'); Write('D');
  FOR Count:=0 TO HIGH(PhoneNum) DO
    Write(PhoneNum[Count]);
  END; (* FOR *)
  Write(CHR(13));
  RS232Code.Read(Char1);
  RS232Code.Read(Char2);
  CASE Char1 OF
    '1' : 
        IF Char2='0' THEN
          Result:=Connect2400; State:=Online;
        ELSE
          Result:=Connect300;  State:=Online;
        END|
    '3' : Result:=NoCarrier;   State:=Offline|
    '4' : Result:=Error;       State:=Offline|
    '5' : Result:=Connect1200; State:=Online|
    '6' : Result:=NoDialTone;  State:=Offline|
    '7' : Result:=Busy;        State:=Offline|
    '8' : Result:=NoAnswer;    State:=Offline
    ELSE  Result:=Error;       State:=Offline;
  END; (* CASE *)
END Call;

