PROCEDURE HangUp;
Dials the number Number (which may contain Hayes dial modifiers) and sets Result accordingly.
Calls: 2 in Serial (Read, Write), 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: Tone), 1 in Graphics (Write), 1 in KeyDispatch (Read) and 1 in Picture (Wait)
Called by: 1 in E250Term (DialRadar), 1 in E300RadarTerm (Online) and 1 in Main (InterLoop)

PROCEDURE HangUp;
BEGIN
END HangUp;

BEGIN  
  RS232Code.Init(    2400,   1, FALSE, FALSE,   8, done);
                (*   BAUD STOP PARITY   EVEN DATA *)
  RS232Code.StartReading;
  Count:=0;
  LOOP
    Write('A'); Write('T'); 
    Write('&'); Write('C'); Write('1'); (* Carrier detect option 1 : 
                                           CDC follows true carrier *)
    Write('&'); Write('D'); Write('3'); (* DTR option 3 : 
                                           Modem resets with DTR *)
    Write('L');                         (* Low speaker volume *)
    Write('M'); Write('1');             (* Speaker on until carrier detect *)
    Write('E');                         (* No command echo *)
    Write('V');                         (* Short-form result codes *)
    Write('X'); Write('4');             (* Wait for dial tone, BUSY *)
    Write('&'); Write('W');             (* Store parameters in permanent mem *)
    Write(CHR(13));
    RS232Code.Read(Response);
    IF Response='0' THEN EXIT; END;
    Count:=Count+1;
    IF Count=4 THEN 
      State:=NoResponse;
      EXIT; 
    END; (* IF *)
  END; (* LOOP *)
END Modem.
