RADARPAS / Modem / ModemCommand (Modula-2 procedure)
PROCEDURE ModemCommand ( Command    : ARRAY OF CHAR;
Disconnects line if connected; otherwise, does nothing.
Calls: 3 in rs (Return Number of recived bytes in buffer: Receive, RxCount, Send), 1 in KeyDispatch (KeyPressed), 1 in this module (ClearBuffer), 1 in RadioRx (Receive) and 1 in TestDB (Tests the Digital Broadcast Kernel as a transient program.: Send)

PROCEDURE ModemCommand
( Command    : ARRAY OF CHAR;
  VAR Result : ResultCode );
(* Sends AT Command to modem, sets result accordingly. *)
VAR
  Count    : CARDINAL;
  Response : ARRAY[0..5] OF CHAR;
  Key      : CHAR;
BEGIN
  rs.Send(Command,Length(Command));
  rs.Send(ASCII.cr,1);
  ClearBuffer;
  Count := 0;
  Key := 000C;
  REPEAT
    IF rs.RxCount()>0 THEN
      rs.Receive(Response[Count],1);
      INC(Count);
    END (* IF *);
    IF IO.KeyPressed() THEN
        Result := NoResponse;
(*        Key := IO.RdKey(); *)
        RETURN;
    END (* IF *);
  UNTIL ( Response[ Count-1 ] = ASCII.cr );
  Response[ Count-1 ] := ASCII.nul;
  IF Compare( Response, '0' ) = 0 THEN
    Result := Ok;
  ELSIF Compare(Response,'1') = 0 THEN
    Result:=Connect300;
  ELSIF Compare(Response,'2') = 0 THEN
    Result:=Ring;
  ELSIF Compare(Response,'3') = 0 THEN
    Result:=NoCarrier;
  ELSIF Compare(Response,'4') = 0 THEN
    Result:=ModemError;
  ELSIF Compare(Response,'5') = 0 THEN
    Result:=Connect1200;
  ELSIF Compare(Response,'6') = 0 THEN
    Result:=NoDialtone;
  ELSIF Compare(Response,'7') = 0 THEN
    Result:=Busy;
  ELSIF Compare(Response,'8') = 0 THEN
    Result:=NoAnswer;
  ELSIF Compare(Response,'10') = 0 THEN
    Result:=Connect2400;
  ELSE
    Result:=NoResponse;
  END; (* IF *)
END ModemCommand;

END Modem.


