PROCEDURE OptionMenu;
Draw the window
Calls: 5 in Graphics (FillArea, GotoXY, SetFunc, SetPlane, +1 more), 2 in this module (SaveOptions, WriteOptionEntry), 1 in E250Term (Options), 1 in Main (OptionMenu) and 1 in Selector (Select)
Called by: 1 in Main (OptionMenu) and 1 in MainRx (ModemLoop)

PROCEDURE OptionMenu;

VAR
  OptionSelect : CARDINAL;
  Key          : CHAR;
  Escape       : BOOLEAN;

CONST
  NumofOptions = 5;

BEGIN

  (* Draw the window *)
  SetPlane( {2} );
  SetFunc( clr, 0 );
  FillArea( 184, 28, 264, 294, CARDINAL(0FFFFH) );
  SetPlane( {3} );
  SetFunc( or, 0 );
  SetWindow( 184, 28, 264, 294 );
  GotoXY( 0, 0 );
  WrStr( '═══════════ OPTIONS ════════════' ); WrLn;
  GotoXY( 0, 266 );
  WrStr( '═════════════════════════════════' ); WrLn;
  WrStr( ' <RET>·Change option  <ESC>·Exit ');

  OptionSelect := 0;
  REPEAT

      SetPlane( {3} );
      SetFunc( clr, 0 );
      FillArea( 184, 42, 264, 140, CARDINAL(0) );

      Select( 184, 42, 448, 182, WriteOptionEntry,
          NumofOptions, OptionSelect, Key, Escape );

      IF Key = ASCII.cr THEN
          CASE OptionSelect OF
            1 : IF ModemPort = 1 THEN
                    ModemPort := 2;
                ELSE
                    ModemPort := 1;
                END (* IF *); |
            2 : IF ModemBaud = 1200 THEN
                    ModemBaud := 2400;
                ELSIF ModemBaud = 2400 THEN
                    ModemBaud := 9600;
                ELSE
                    ModemBaud := 1200;
                END (* IF *); |
            4 : IF ClockType = 1 THEN
                    ClockType := 2;
                ELSE
                    ClockType := 1;
                END (* IF *);
          END (* CASE *);
      END (* IF *);

  UNTIL Key = ASCII.esc;

  SetPlane( {2,3} );
  SetFunc( clr, 0 );
  FillArea( 184, 28, 264, 294, CARDINAL(0) );
  SetWindow( 0, 0, 639, 349 );

  SaveOptions;

END OptionMenu;

