PROCEDURE Wait;
Wait for a picture to be ready to send. Must call Download immediately or picture data may be lost.
Calls: 2 in Serial (Read, Write), 1 in Control (Delay), 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: Delay), 1 in Graphics (Write), 1 in KeyDispatch (Read), 1 in Modem (Call), 1 in this module (Download), 1 in rs (Return Number of recived bytes in buffer: Send) and 1 in TestDB (Tests the Digital Broadcast Kernel as a transient program.: Send)
Called by: 1 in Modem (HangUp), 1 in RadarVersion2point0 (Interact), 1 in ScrnSend (TxProcess), 1 in Serial (Timer) and 1 in Test (Serial file transfers: RxFiles)

PROCEDURE Wait;
(* Wait for a picture to be ready to send.  Must call Download immediately
   or picture data may be lost. *)
VAR
  WaitCode     : ARRAY[0..26] OF CHAR;
  Count        : CARDINAL;
BEGIN
  Write('Z'); Delay(15);
  Write(RadarSendPic);
  Count:=0;
  REPEAT
    Read(WaitCode[Count]);
    INC(Count);
  UNTIL (Count>=3) AND (WaitCode[Count-1]=375c) AND
    (WaitCode[Count-2]=376c) AND (WaitCode[Count-3]=377c);
END Wait;

RADARPAS / Pictures / AddPicture (Modula-2 procedure)
PROCEDURE AddPicture( VAR PicList : ARRAY OF PictureRec;
Displays indicated picture. Assumes current directory is station's directory
Calls: 1 in this module (FileName) and 1 in RadarTx (TransmitPic)
Called by: 2 in Main (DoAuto, InterLoop), 1 in MainRx (ModemLoop) and 1 in RadarStore (InitStationDir)

PROCEDURE AddPicture( VAR PicList : ARRAY OF PictureRec;
                       VAR MaxPic : CARDINAL;
                       ForPicture : PictureRec;
                       VAR Number : CARDINAL );

(* Adds a new picture header into its proper position in the
   picture list *)


VAR

  Count : CARDINAL;
  PicFileName : ARRAY [ 0..11 ] OF CHAR;

BEGIN

  (* First, search for the chronological position to insert the
     picture header *)
  Number := 0;
  LOOP

      IF Number >= MaxPic THEN

          EXIT;

      END (* IF *);

      (* Check to see if the date is the same *)
      IF PicList[Number].TimeofPic.day = ForPicture.TimeofPic.day THEN

          (* Is the time earlier? *)
          IF PicList[Number].TimeofPic.minute <
          ForPicture.TimeofPic.minute THEN

              EXIT;

          END (* IF *);

      (* Is the date earlier? *)
      ELSIF PicList[Number].TimeofPic.day < ForPicture.TimeofPic.day THEN

          EXIT;

      END; (* IF *)

      INC( Number );

  END; (* LOOP *)

  (* Increment picture count only if within range *)
  IF MaxPic < HIGH( PicList ) THEN

      INC( MaxPic );

  END (* IF *);

  (* Move all the later pictures up *)
  FOR Count := MaxPic TO Number+1 BY -1 DO

      PicList[Count] := PicList[Count-1];

  END; (* FOR *)

(* MOVE TO MAIN BODY
  (* Check if CurrentPicture was also moved up *)
  IF CurrentPicture > Number THEN

      INC( CurrentPicture );

  END (* IF *);
*)

  (* Insert picture header into its place *)
  PicList[Number] := ForPicture;

(* SCA TRANSMISSION *)

(*  IF Number = 0 THEN
      FileName( ForPicture, PicFileName );
      TransmitPic( PicFileName, ForPicture.Data^, ForPicture.Size );
  END (* IF *); *)

(* END SCA TRANSMISSION *)

END AddPicture;

RADARPAS / Pictures / DeletePicture (Modula-2 procedure)
PROCEDURE DeletePicture( VAR PicList : ARRAY OF PictureRec;
Adds a new picture header into its proper position in Station's picture list
Calls: 1 in this module (FileName) and 1 in Store (DeletePicture)
Called by: 2 in RadarStore (PictureMenu, WriteEntry), 1 in Main (InterLoop), 1 in MainRx (ModemLoop) and 1 in this module (PictureMenu)

PROCEDURE DeletePicture( VAR PicList : ARRAY OF PictureRec;
                          VAR MaxPic : CARDINAL;
                          PictureNum : CARDINAL );

(* Deletes a picture from the current station's picture list, as well
   as the corresponding file.  Assumes the current directory is the
   station's directory *)

VAR

  DataFileName : ARRAY [ 0..10 ] OF CHAR;
      DataFile : File;
         Count : CARDINAL;

BEGIN

  (* First, delete the picture's file *)
  FileName( PicList[PictureNum],
      DataFileName );
  Erase( DataFileName );

  (* Now, if the picture was in memory, free
         up the memory *)
  IF PicList[PictureNum].Data # NIL THEN

      DEALLOCATE( PicList[PictureNum].Data,
          PicList[PictureNum].Size );
      PicList[PictureNum].Data := NIL;

  END (* IF *);

  (* Move all the pictures above down *)
  FOR Count := PictureNum TO MaxPic DO

      PicList[Count] := PicList[Count+1];

  END (* FOR *);

  (* Adjust the picture count *)
  DEC(MaxPic);

END DeletePicture;



