PROCEDURE ExecCom;
* Main Routines *
Calls: 3 in this module (ToggleGraphics, WriteGfx, WriteHelp) and 3 in Radar_Terminal (ClearScreen, SelectPlane, WriteRngMks)
Called by: 3 in this module (InterLoop, ModemLoop, RxPicLoop), 3 in Radar_Terminal (DDelay, RxGraphLoop, ShowLoop) and 2 in E300_Radar_Terminal (RxPicLoop, Sync)

PROCEDURE ExecCom;
  BEGIN
    CASE UpCase(Key) OF (*Process regular key codes*)
      'G'  : ToggleGraphics;
      'R'  : BEGIN
               RngMksOn:=not RngMksOn;
               IF RngMksOn THEN
                 WriteRngMks
               ELSE
                 SelectPlane([2,3]); ClearScreen;
                 IF Gfx1On THEN WriteGfx(Map1); END;
                 IF Gfx2On THEN WriteGfx(Map2); END;
               END;
             END;
      'H'  : BEGIN
               HelpOn:=not HelpOn;
               WriteHelp;
             END;
      '1'  : IF StationName<>'' THEN
               Gfx1On:=not Gfx1On;
               IF Gfx1On THEN
                 WriteGfx(Map1);
               ELSE
                 SelectPlane([2,3]); ClearScreen;
                 IF RngMksOn THEN WriteRngMks; END;
                 IF Gfx2On THEN WriteGfx(Map2); END;
               END;
             END;
      '2'  : IF StationName<>'' THEN
               Gfx2On:=not Gfx2On;
               IF Gfx2On THEN
                 WriteGfx(Map2);
               ELSE
                 SelectPlane([2,3]); ClearScreen;
                 IF RngMksOn THEN WriteRngMks; END;
                 IF Gfx1On THEN WriteGfx(Map1); END;
               END;
             END;
    END;
  END;

RADARPAS / RADAR / GRLine (Turbo Pascal procedure)
PROCEDURE GRLine(X1,Y1,X2,Y2 : INTEGER);
Draws a line between two points using digital differential analyzer algorithm, plotting pixels via GRPlot function on screen graphics.
Calls: 1 in Radar_Terminal (GRPlot)
Called by: 1 in this module (WriteGfx) and 1 in Radar_Terminal (WriteGfx)

PROCEDURE GRLine(X1,Y1,X2,Y2 : INTEGER);
VAR
  Add            : real;
  Dir            : INTEGER;
  XReal,YReal    : real;
BEGIN
  XReal:=X1; YReal:=Y1;
  IF Abs(Y2-Y1)>Abs(X2-X1) THEN
    Add:=(X2-X1)/Abs(Y2-Y1);
    IF Y2>Y1 THEN
      Dir:=1;
    ELSE
      Dir:=-1;
    END; (* IF *)
    WHILE Y1<>Y2 DO
      GRPlot(Trunc(XReal),Y1);
      XReal:=XReal+Add;
      Y1:=Y1+Dir;
    END; (* WHILE *)
  ELSE
    IF X2<>X1 THEN
      Add:=(Y2-Y1)/Abs(X2-X1);
    ELSE
      Add:=0;
    END; (* IF *)
    IF X2>X1 THEN
      Dir:=1
    ELSE
      Dir:=-1;
    END; (* IF *)
    WHILE X1<>X2 DO BEGIN
      GRPlot(X1,Trunc(YReal));
      YReal:=YReal+Add;
      X1:=X1+Dir;
    END; (* WHILE *)
  END; (* IF *)
END GRLine;

