RADARPAS / RADAR / RxPicLoop (Turbo Pascal procedure)
PROCEDURE RxPicLoop;
Receives radar picture data via serial port, displays sweep lines on screen, handles abort requests, saves completed picture to memory buffer.
Calls: 8 in Radar_Terminal (Ask, ClearScreen, DispLine, DrawScale, +4 more), 4 in this module (ExecCom, GRMessage, ReadKbd, WriteHelp) and 1 in RADCGA (DispLine)
Called by: 1 in E300_Radar_Terminal (RxPicLoop) and 1 in this module (InterLoop)

PROCEDURE RxPicLoop;
  VAR
    AbortPending   : BOOLEAN;
    ContWrite      : BOOLEAN;
  BEGIN
    WriteHelp;
    SendCom(SendPic,200);
    IF not Response THEN Exit; END;
    SelectPlane([0,1]); ClearScreen;
    GRMessage('WAITING FOR PICTURE',false);
    DrawScale;
    Mode:=WaitPic; BufPtr:=Addr(GRBuf);
    LastLine:=0; AbortPending:=false;
    REPEAT
      IF KeyPressed THEN
        ReadKbd;
        ExecCom;
        IF Key=#27 THEN
          IF Ask('ABORT PICTURE') THEN Key:=^Q; END;
        END;
        GRMessage('WAITING FOR PICTURE',false);
      END;
    UNTIL (Key=^Q) or (Mode=RxPic);
    IF Mode=RxPic THEN
      WriteAt:=-20000; LineAt:=-20001; PicSaveAt:=-20000;
      GRMessage('RECEIVING PICTURE',false);
      REPEAT
        REPEAT
          inline($FA); ContWrite:=LineAt>=WriteAt; inline($FB);
          IF ContWrite THEN
            DispLine(PicSave[WriteAt]);
            WriteAt:=WriteAt+LineSize;
          END;
        UNTIL not ContWrite;
        IF KeyPressed THEN
          ReadKbd;
          IF AbortPending THEN
            IF UpCase(Key)='Y' THEN
              Tx('Y'); Tx('Y');
              GRMessage('PICTURE ABORTED',true);
              Tx('Y');
              Key:=^Q;
            ELSE
              GRMessage('RECEIVING PICTURE',false);
              AbortPending:=false;
            END
          ELSE
            ExecCom;
            IF Key IN ['1','2','G','R','H'] THEN
              GRMessage('RECEIVING PICTURE',false);
            END;
            IF Key=#27 THEN
              AbortPending:=true;
              GRMessage('ABORT PICTURE? (Y/N)',false);
            END;
          END;
        END;
      UNTIL (Key=^Q) or (LastLine>=352) or (Mode=Modem);
      IF LastLine>=352 THEN
        IF Mode<>Modem THEN
          HangUp;
          Delay(500);
          Mode:=Modem;
        END;
        GRMessage('SAVING PICTURE...',false);
        SavePic(PicSaveAt+20000);
        PictureSaved:=true;
      END ELSE
        Mode:=Interactive;
        PictureSaved:=false;
      END;
    END;
    GRMessage('',false);
    Key:=#0;
    WriteHelp;
  END;

