PROCEDURE Storage;
Displays stored radar pictures, allows selection, deletion, and loading via keyboard; works with screen, file system, and Pic[] data structure.
Calls: 4 in this module (ReadKbd, UnWindow, Window, WriteTime) and 3 in Radar_Terminal (Ask, FetchPic, GotoXY)
Called by: 2 in this module (ModemLoop, WriteHelp) and 1 in Radar_Terminal (InitRS232)

PROCEDURE Storage;
  VAR
    SelectPic,
    TopPic     : INTEGER;
    Count      : INTEGER;
    PicFile    : file;
  BEGIN
    Window(27,1,25,21);
    Write('════════ STORAGE ═════════');
    Write('  ·Time· ·Tilt·Range·Gain·');
    GotoXY(0,18);
    Write('══════════════════════════');
    Writeln(' RET · Select Picture');
    Writeln(' F1  · Delete Picture');
    Writeln(' ESC · Exit');
    SelectPic:=CurrPic;
    TopPic:=MaxPic+1;
    REPEAT
      IF (SelectPic<TopPic) or (SelectPic>TopPic+15) THEN
        IF SelectPic<=8 THEN TopPic:=1 ELSE TopPic:=SelectPic-8; END;
        GotoXY(0,2);
        FOR Count:=TopPic TO TopPic+15 DO
          IF Count<=MaxPic THEN WITH Pic[Count] DO
            Write('  ');
            WriteTime(Time);
            Write(TiltVal[Tilt]:4);
            Write(RangeVal[Range]:6);
            IF Gain<17 THEN Write(Gain:5) ELSE Write('  PRE'); END;
            WriteLn;
          ELSE
            WriteLn('                        ');
          END;
        END;
      END;
      GotoXY(0,SelectPic-TopPic+2);
      IF SelectPic<>0 THEN Write('->');
      ReadKbd;
      CASE Key OF
        '+' : IF SelectPic<MaxPic THEN SelectPic:=SelectPic+1; END;
        '-' : IF SelectPic>0 THEN SelectPic:=SelectPic-1; END;
        ';' : IF SelectPic>0 THEN
                IF Ask('DELETE THIS PICTURE?') THEN
                  Assign(PicFile,Pic[SelectPic].FileName);
                  Erase(PicFile);
                  FOR Count:=SelectPic+1 TO MaxPic DO Pic[Count-1]:=Pic[Count];
                  TopPic:=MaxPic+1;
                  MaxPic:=MaxPic-1;
                END;
              END;
      END;
      Write(^M,'  ');
    UNTIL (Key=^[) or (Key=^M);
    UnWindow;
    IF Key=^M THEN
      CurrPic:=SelectPic;
      FetchPic;
    END;
    Key:=#0;
  END;

