Calls: 2 in this module (SelectFunc, WriteTime) and 2 in Radar_Terminal (GotoXY, SelectPlane)
Called by: 3 in E300_Radar_Terminal (InitEGA, RxPicLoop, Sync)

PROCEDURE WriteParams;
  BEGIN
    SelectFunc(_Clr); SelectPlane([2]);
    IF CurrPic>0 THEN
      WITH Pic[CurrPic] DO
        GotoXY(8,0); Write(TiltVal[Tilt]:3);
        GotoXY(72,0); WriteTime(Time);
        GotoXY(8,24); Write(RangeVal[Range]:3);
        GotoXY(72,24); IF Gain<17 THEN Write(Gain:4) ELSE Write(' PRE');
        IF Mode=Interactive THEN
          SelectPlane([0]); GotoXY(36,0);
          CASE RT OF
            0   : Write(' RT OFF ');
            1,2 : Write(' RT ON  ');
          END;
        END;
      END
    ELSE
      GotoXY(8,0); Write('XXX');
      GotoXY(72,0); Write('XX:XX  ');
      GotoXY(8,24); Write('XXX');
      GotoXY(72,24); Write(' XXX');
    END; (* IF *)
  END;

RADARPAS / RADAR / WriteTime (Turbo Pascal procedure)
PROCEDURE WriteTime(Time : TimeRec);
* Graphics Routines *
Called by: 3 in this module (InitEGA, Storage, WriteParams)

PROCEDURE WriteTime(Time : TimeRec);
BEGIN
  CASE Clock OF
    0 :
      IF Time.Hour<13 THEN
        Write(Time.Hour:2,':')
      ELSE
        Write((Time.Hour-12):2,':')
      END; |
    1 :
      Write(Time.Hour:2,':'); |
  END; (* CASE *)
  IF Time.Minute<10 THEN
    Write('0');
  END; (* IF *)
  Write(Time.Minute);
  IF Clock=0 THEN
    IF Time.Hour>12 THEN
      Write('pm')
    ELSE
      Write('am')
    END; (* IF *)
  ELSE
    Write('  ')
  END; (* IF *)
END WriteTime;


