procedure InitRS232; {& interrupt routine}
& interrupt routine
Calls: 1 in INTR (RS232Interupt), 1 in Modem (RS232Interupt) and 1 in RADAR (Storage)
Called by: 1 in this module (Initialize) and 1 in RADIO (TxCheck)

procedure InitRS232; {& interrupt routine}
  begin
    DSave:=DSeg; Buf:='';
    with Registers do begin
      AH:=$25;
      if ComPort=$3F8 then AL:=$0C else AL:=$0B;
      DX:=Ofs(RS232Interupt)+7;
      DS:=CSeg;
      Intr($21,Registers);
    end;
    for I:=ComPort to ComPort+6 do J:=port[I];
    Port[ComPort+3]:=$80; {Set baud rate access bit}
    Case RadarBaud of
      1200 : Port[ComPort]:=96; {Set baud rate (2400 = 48, 1200 = 96)}
      2400 : Port[ComPort]:=48;
    end;
    Port[ComPort+1]:=$00;
    Port[ComPort+3]:=$03; {Set Line Control Data (8 data,1 stop,0 parity)}
    Port[ComPort+1]:=$09;
    Port[ComPort+4]:=$0B; {Set DTR & RTS high}
    if ComPort=$3F8 then ComPort:=$2F8 else ComPort:=$3F8;
    for I:=ComPort to ComPort+6 do J:=port[I]; (* Set transmission com port *)
    Port[ComPort+3]:=$80; {Set baud rate access bit}
    Case HostBaud of
      1200 : Port[ComPort]:=96; {Set baud rate (2400 = 48, 1200 = 96)}
      2400 : Port[ComPort]:=48;
    end;
    Port[ComPort+1]:=$00;
    Port[ComPort+3]:=$03; {Set Line Control Data (8 data,1 stop,0 parity)}
    Port[ComPort+1]:=$09;
    Port[ComPort+4]:=$0B; {Set DTR & RTS high}
    if ComPort=$3F8 then ComPort:=$2F8 else ComPort:=$3F8;
    UsrOutPtr:=Ofs(Tx);
  end;


