Calls: 2 in RADAR (ReadKbd, ReadStr)
Called by: 2 in this module (AddStation, SelectStation), 1 in RADAR (ReadStr) and 1 in Radar_Terminal_Zoom_Test (DeInit)

function ReadStr(Len : byte) : LineType;
  var
    Line           : LineType;
  begin
    Line:=''; Write('█');
    repeat
      ReadKbd; Key:=UpCase(Key);
      if Length(Line)>=Len then begin
        Sound(440); Delay(50); NoSound;
        if Key<>^M then Key:=#0;
      end;
      case Key of
        #32..#126 : begin
          Line:=Line+Key;
          Write(^H,Key,'█');
        end;
        ^H : if Length(Line)>0 then begin
          Write(^H,^H,'█ ',^H);
          Line:=Copy(Line,1,Length(Line)-1);
        end;
      end;
    until Key=#13;
    Write(^H,' '); ReadStr:=Line;
  end;


