RADARPAS / Radar_Terminal_Zoom_Test / getarea (Turbo Pascal procedure)
procedure getarea;
Allocates memory buffers and reads 175x40 pixel data from EGA video memory maps 0 and 1, storing them in redbuf and grnbuf arrays for radar display processing.
Called by: 1 in this module (stretch)

procedure getarea;
var XCount, YCount : integer;
begin
  New(redbuf); New(grnbuf);
  for YCount:=0 to 174 do
    for XCount:=0 to 39 do begin
      Port[$3CE]:=$04; Port[$3CF]:=$00; (* Read map 0 *)
      redbuf^[YCount,XCount]:=Mem[$A000:(88+YCount)*80+(20+XCount)];
      Port[$3CE]:=$04; Port[$3CF]:=$01; (* Read map 1 *)
      grnbuf^[YCount,XCount]:=Mem[$A000:(88+YCount)*80+(20+XCount)];
    end;
end;

