function getpix(x,y : integer) : integer;
var
  r,g : byte;
begin
  r:=redbuf^[y,x div 8] and ($80 shr (x and $07));
  g:=grnbuf^[y,x div 8] and ($80 shr (x and $07));
  if r=0 then
    if g=0 then
      getpix:=0
    else
      getpix:=1
  else
    if g=0 then
      getpix:=3
    else
      getpix:=2;
end;

