RADARPAS / Radar_Terminal_Zoom_Test / stretch (Turbo Pascal procedure)
procedure stretch(x,y,dx,dy : integer; xs,ys : real);
Compute y address for source
Calls: 3 in this module (getarea, getpix, setpix), 2 in Radar_Terminal (ClearScreen, SelectPlane) and 1 in RADAR (GRMessage)

procedure stretch(x,y,dx,dy : integer; xs,ys : real);
var
  i,j,ix,iy  : integer;
  A,B,C,D,
  xAB,xCD,
  xx,yy,V    : real;
begin
  GRMessage('COPYING AREA...',false);
  getarea;
  SelectPlane([0,1,2,3]); ClearScreen;
  GRMessage('STRETCHING...',false);
  for i:=1 to dy-1 do begin
    yy:=(i-1)/ys;  (* Compute y address for source *)
    iy:=trunc(yy); (* Round to integer *)
    yy:=yy-iy;     (* Leave only fraction of address *)
    for j:=1 to dx-1 do begin
      xx:=(j-1)/xs;
      ix:=trunc(xx);
      xx:=xx-ix;
      A:=getpix(ix+1,iy);
      B:=getpix(ix,iy);
      C:=getpix(ix+1,iy+1);
      D:=getpix(ix,iy+1);
      xAB:=A+(B-A)*xx;
      xCD:=C+(D-C)*xx;
      V:=xAB+((xCD-xAB)*yy)+0.5;
      setpix(x+j,y+i,trunc(V));
    end;
  end;
  GRMessage('',false);
end;


