RADARPAS / ScreenHandler / ComprLine (Modula-2 procedure)
PROCEDURE ComprLine( Number : CARDINAL;
GotoXY( 50, 0 ); WrCard( Count, 5 ); WrCard( SrcAt, 5 ); WrCard( DestAt, 5 );
Calls: 2 in Graphics (GotoXY, SetPlane) and 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: GotoXY)
Called by: 2 in Main (DoAuto, InterLoop) and 1 in Convert (GetLine)

PROCEDURE ComprLine( Number        : CARDINAL;
                     VAR Red, Grn  : ARRAY OF BYTE;
                     VAR Buffer    : ARRAY OF BYTE;
                     VAR DestAt    : CARDINAL );
VAR

   SrcAt,
   Count : CARDINAL;

BEGIN

  SetPlane( {0} );
  Move( ADR(Red), ADR(Screen[ Number * 35 DIV 48 * 80 ]), 160 );

  SetPlane( {1} );
  Move( ADR(Grn), ADR(Screen[ Number * 35 DIV 48 * 80 ]), 160 );

  SrcAt := 0;
  REPEAT

      IF Red[SrcAt] = BYTE(00H) THEN

          Count := 0;
          WHILE ( SrcAt <= HIGH(Red) ) & ( Red[SrcAt] = BYTE(00H) )
              & ( Count < 255 ) DO

              INC( SrcAt );
              INC( Count );
(*              GotoXY( 50, 0 );
              WrCard( Count, 5 );
              WrCard( SrcAt, 5 );
              WrCard( DestAt, 5 ); *)

          END (* WHILE *);

          Buffer[DestAt] := 00H;
          Buffer[DestAt+1] := BYTE(Count);
          INC( DestAt, 2 );
(*          GotoXY( 300, 0 );
          WrStr('OUT OF LOOP'); *)

      ELSIF Red[SrcAt] = BYTE(0FFH) THEN

          Count := 0;
          WHILE ( SrcAt <= HIGH(Red) ) & ( Red[SrcAt] = BYTE(0FFH) )
              & ( Count < 255 ) DO

              INC( SrcAt );
              INC( Count );

          END (* WHILE *);

          Buffer[DestAt] := 377C;
          Buffer[DestAt+1] := BYTE(Count);
          INC( DestAt, 2 );

      ELSE

          Buffer[DestAt] := Red[SrcAt];
          INC( DestAt );
          INC( SrcAt );

      END (* IF *);

  UNTIL SrcAt >= HIGH(Red);


  SrcAt := 0;
  REPEAT

      IF Grn[SrcAt] = BYTE(00H) THEN

          Count := 0;
          WHILE ( SrcAt <= HIGH(Grn) ) & ( Grn[SrcAt] = BYTE(00H) )
              & ( Count < 255 ) DO

              INC( SrcAt );
              INC( Count );

          END (* WHILE *);

          Buffer[DestAt] := 00H;
          Buffer[DestAt+1] := BYTE(Count);
          INC( DestAt, 2 );

      ELSIF Grn[SrcAt] = BYTE(0FFH) THEN

          Count := 0;
          WHILE ( SrcAt <= HIGH(Grn) ) & ( Grn[SrcAt] = BYTE(0FFH) )
              & ( Count < 255 ) DO

              INC( SrcAt );
              INC( Count );

          END (* WHILE *);

          Buffer[DestAt] := 377C;
          Buffer[DestAt+1] := BYTE(Count);
          INC( DestAt, 2 );

      ELSE

          Buffer[DestAt] := Grn[SrcAt];
          INC( DestAt );
          INC( SrcAt );

      END (* IF *);

  UNTIL SrcAt >= HIGH(Grn);


END ComprLine;

