RADARPAS / ScreenHandler / Prompt (Modula-2 procedure)
PROCEDURE Prompt(String : ARRAY OF CHAR; VAR Response : ARRAY OF CHAR);
Prints message at bottom of screen. Call Message('') to turn off
Calls: 4 in Graphics (GetWindow, GotoXY, SetFunc, SetWindow), 1 in CDScrn (Message), 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: GotoXY) and 1 in Screen (For E300 Radar Terminal: Message)
Called by: 1 in Auto (AddProgram), 1 in E250Term (Options), 1 in Main (AutoMenu) and 1 in Stations (Pointer to the next link in the linked list.: AddStation)

PROCEDURE Prompt(String : ARRAY OF CHAR; VAR Response : ARRAY OF CHAR);
VAR
  MessString : ARRAY [ 0..79 ] OF CHAR;
  X1, Y1, XS, YS : INTEGER;
  Key : CHAR;
BEGIN
  GetWindow( X1, Y1, XS, YS );
  SetWindow( 0, 0, 639, 349 );
  Concat(MessString,String,'                              ');
  MessString[ Length(String)+HIGH(Response) ] := 000C;
  Message( MessString );
  SetFunc( clr, 0 );
  Copy( Response, '' );
  REPEAT
    GotoXY(320-MessLength*4+Length(String)*8,336);
    WrStr( Response );
    WrStr( '█ ' );
    Key := RdKey();
    IF ( Key >= ' ' ) & ( Key <= '~' ) &
        ( Length(Response) < HIGH( Response ) ) THEN

        Concat( Response, Response, Key );

    ELSIF ( Key = ASCII.bs ) & ( Length(Response) > 0 ) THEN

        Slice( Response, Response, 0, Length(Response)-1 );

    END (* IF *);

  UNTIL ( Key = ASCII.cr );
  Message( '' );
  SetWindow( X1, Y1, XS, YS );
END Prompt;

