PROCEDURE WritePic( VAR Buffer : ARRAY OF BYTE; BufSize : CARDINAL );
SetFunc( clr, 0 ); Graph.Line( 639, 0, 639, 349, 4 ); Graph.Line( 0, 349, 0, 0, 4 );
Calls: 2 in Graphics (SetPlane, Write), 1 in CDScrn (Message), 1 in E250Term (WritePic), 1 in RadarRx (WritePic), 1 in Screen (For E300 Radar Terminal: Message) and 1 in Serial (Write)
Called by: 1 in E250Term (WritePic), 1 in MainRx (ModemLoop), 1 in Pictures (The flags which store the state of a picture: SelectPicture) and 1 in RadarRx (WritePic)

PROCEDURE WritePic( VAR Buffer : ARRAY OF BYTE; BufSize : CARDINAL );

VAR
  TCount,
   SrcAt,
  DestAt,
  LineAt,
   Count : CARDINAL;
  RedMap : BOOLEAN;

BEGIN

  SrcAt := 0;
  DestAt := 0;
  LineAt := 0;
  RedMap := TRUE;
  Count := 0;
  TCount := 0;
  SetPlane( {0} );

  WHILE ( SrcAt <= BufSize ) & ( DestAt <= 28000 ) DO

      IF ( Buffer[SrcAt] = BYTE(00H) ) OR ( Buffer[SrcAt] = BYTE(0FFH) ) THEN

          (* Write fill to next 80 byte boundary *)
          IF Count = 0 THEN
              Count := CARDINAL(Buffer[SrcAt+1]);
              TCount := TCount + Count;
          END (* IF *);

          IF Count <= 80 - ( DestAt MOD 80 ) THEN

              Fill( ADR(Screen[DestAt]), Count, Buffer[SrcAt] );
              INC( DestAt, Count );
              Count := 0;
              INC( SrcAt, 2 );

          ELSE

              Fill( ADR(Screen[DestAt]), 80 - ( DestAt MOD 80 ),
                  Buffer[SrcAt] );
              Count := Count + ( DestAt MOD 80 ) - 80;
              DestAt := DestAt + 80 - ( DestAt MOD 80 );

          END (* IF *);

      ELSE

          Screen[DestAt] := Buffer[SrcAt];
          INC( DestAt );
          INC( SrcAt );
          INC( TCount );

      END (* IF *);

      IF ( DestAt MOD 80 ) = 0 THEN

          INC( LineAt );

          IF ~ ODD(LineAt) THEN

              RedMap := ~ RedMap;

              IF RedMap THEN

                  SetPlane( {0} );
                  DestAt := LineAt * 35 DIV 48 * 80;

              ELSE

                  DEC( LineAt, 2 );
                  SetPlane( {1} );
                  DestAt := LineAt * 35 DIV 48 * 80;

              END (* IF *);

          END (* IF *);

      END (* IF *);

  END (* WHILE *);
(*  Message( 'TOTAL:     ' );
  WrChar( ASCII.bs );
  WrChar( ASCII.bs );
  WrChar( ASCII.bs );
  WrChar( ASCII.bs );
  WrChar( ASCII.bs );
  WrCard( TCount, 1 ); *)
  FullPic := ( LineAt >= 476 );

END WritePic;

