RADARPAS / ScreenHandler / WriteTime (Modula-2 procedure)
PROCEDURE WriteTime(ForTime : Time);
Set to TRUE to write time in 24 hour format, FALSE for am/pm format
Calls: 2 in Graphics (Write, WriteString) and 1 in Serial (Write)
Called by: 2 in Auto (ProgramMenu, WriteProgramEntry), 1 in Pictures (The flags which store the state of a picture: WritePictureEntry), 1 in RadarStore (WriteEntry), 1 in Screen (For E300 Radar Terminal: WriteParams) and 1 in this module (WriteParams)

PROCEDURE WriteTime(ForTime : Time);
(* Writes time in 7 spaces *)
VAR
  Hour, Minute : CARDINAL;
BEGIN
  Hour:=ForTime.minute DIV 60;
  Minute:=ForTime.minute MOD 60;
  IF ArmyTime OR (Hour<=12) THEN
    WriteCard(Hour,2);
  ELSIF (Hour<=23) THEN
    WriteCard(Hour-12,2);
  ELSE
    WriteCard(24,2);
  END; (* IF *)
  Write(':');
  IF Minute<10 THEN Write('0'); END;
  WriteCard(Minute,0);
  IF ArmyTime THEN
    WriteString('  ');
  ELSIF Hour>11 THEN
    WriteString('pm');
  ELSE
    WriteString('am');
  END; (* IF *)
END WriteTime;

RADARPAS / ScrnSend / Compr (Modula-2 procedure)
PROCEDURE Compr;
Set color don't care to unselected planes.
Called by: 1 in this module (TxProcess)

PROCEDURE Compr;

VAR

   SrcAt,
   Count : CARDINAL;

BEGIN

  SrcAt := 0;
  REPEAT

      IF Scrn[SrcAt] = BYTE(00H) THEN

          Count := 0;
          WHILE ( SrcAt <= HIGH(Scrn) ) & ( Scrn[SrcAt] = BYTE(00H) )
              & ( Count < 255 ) DO

              INC( SrcAt );
              INC( Count );

          END (* WHILE *);

          Buffer[ DestAt ] := 00H;
          Buffer[ DestAt+1 ]
              := BYTE(Count);
          INC( DestAt, 2 );

      ELSIF Scrn[SrcAt] = BYTE(0FFH) THEN

          Count := 0;
          WHILE ( SrcAt <= HIGH(Scrn) ) & ( Scrn[SrcAt] = BYTE(0FFH) )
              & ( Count < 255 ) DO

              INC( SrcAt );
              INC( Count );

          END (* WHILE *);

          Buffer[ DestAt ] := 377C;
          Buffer[ DestAt+1 ] := BYTE(Count);
          INC( DestAt, 2 );

      ELSE

          Buffer[ DestAt ] := Scrn[SrcAt];
          INC( DestAt );
          INC( SrcAt );

      END (* IF *);

  UNTIL SrcAt >= HIGH(Scrn);

END Compr;

RADARPAS / ScrnSend / TxProcess (Modula-2 procedure)
PROCEDURE TxProcess;
Blank map areas of screen
Calls: 5 in rs (Return Number of recived bytes in buffer: Install, Receive, RxCount, Send, +1 more), 2 in Graphics (SetPlane, Write), 2 in KeyDispatch (KeyPressed, Read), 2 in RS232 (For E300 Radar Terminal: Initialize, Mode), 2 in Serial (Read, Write), 1 in Control (Delay), 1 in DB (VAR Buffer: TxProcess), 1 in E300PC (Storage), 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: Delay), 1 in Picture (Wait), 1 in RadioRx (Receive), 1 in Screen (For E300 Radar Terminal: Initialize), 1 in this module (Compr) and 1 in TestDB (Tests the Digital Broadcast Kernel as a transient program.: Send)
Called by: 1 in DB (VAR Buffer: TxProcess)

PROCEDURE TxProcess;

VAR
    P, Y  :  CARDINAL;
    AckChar  :  CHAR;

BEGIN

    WHILE rs.RxCount() > 0 DO

        rs.Receive( AckChar, 1 );

    END (* WHILE *);

    LOOP

        IF ~ Debug THEN

            DestAt := 0;
            FOR P := 0 TO 3 DO
                IF P # 2 THEN
                    SYSTEM.DI;
                    SetPlane( {P} );
                    Lib.Move( ADR( RealScrn ), ADR( Scrn ), SIZE( Scrn ) );
                    SetPlane( {} );
                    SYSTEM.EI;
                    IF P = 3 THEN

                        FOR Y := 0 TO 40 DO
                            Lib.Fill( ADR( Scrn[ Y*80+14 ] ), 52, 0 );
                        END (* FOR *);
                        Lib.Fill( ADR( Scrn[ Y*80+14 ]), 21600, 0 );
                        FOR Y := 310 TO 350 DO
                            Lib.Fill( ADR( Scrn[ Y*80+14 ] ), 52, 0 );
                        END (* FOR *);

                        (* Blank map areas of screen *)
                    END (* IF *);
                ELSE
                    Lib.Fill( ADR( Scrn ), SIZE( Scrn ), 0 );
                END (* IF *);

                Compr;

            END (* FOR *);

        END (* IF *);

        BufAt := 0;
        REPEAT

            IF Debug THEN
                IO.WrStr( ' Sending block ' );
                IO.WrCard( BufAt DIV BlockSize, 1 );
                IO.WrStr( '...' );
                ExitFlag := IO.KeyPressed();
            END (* IF *);

            (* Send block and checksum *)
            rs.Send( BufAt, 2 );
            rs.Send( Buffer[ BufAt ], BlockSize );
            rs.Send( CRC.CalcCRC( ADR( Buffer[ BufAt ] ),
                BlockSize ), 2 );

            (* Wait for tx buffer to clear *)
            WHILE rs.TxCount() > 0 DO

                Process.Delay( 1 );

            END (* WHILE *);

            IF Debug THEN
                IO.WrStr( "waiting for Ack...'" );
                ExitFlag := IO.KeyPressed();
            END (* IF *);

            (* Receive Acknowledge char *)
            WHILE rs.RxCount() = 0 DO

                Process.Delay( 1 );
                ExitFlag := ( Debug & IO.KeyPressed() );

            END (* WHILE *);
            rs.Receive( AckChar, 1 );

            IF Debug THEN
                IO.WrChar( AckChar ); IO.WrStr( "' received." ); IO.WrLn;
            END (* IF *);

            IF AckChar = 'A' THEN

                INC( BufAt, BlockSize );

            END (* IF *);

        UNTIL ( AckChar = 'X') OR ( BufAt > DestAt+BlockSize );

        Process.Delay( 18 );

    END (* LOOP *);

END TxProcess;


