PROCEDURE StationMenu( VAR StationList : StationPtr;
WITH
Calls: 5 in Graphics (FillArea, GotoXY, SetFunc, SetPlane, +1 more), 4 in this module (AddStation, DelStation, SelectStation, WriteStationEntry), 1 in CDScrn (ClearScreen), 1 in E250Term (Redraw), 1 in E300PC (Select), 1 in Environment (ROLLINS MEDICAL/DENTAL SYSTEMS: GotoXY), 1 in Map (ClearScreen), 1 in Menu (Select), 1 in RadarStore (StationMenu), 1 in RadarVersion2point0 (StationMenu), 1 in Screen (For E300 Radar Terminal: ClearScreen), 1 in ScreenHandler (Redraw) and 1 in Selector (Select)
Called by: 1 in RadarStore (StationMenu) and 1 in RadarVersion2point0 (StationMenu)

PROCEDURE StationMenu(   VAR StationList : StationPtr;
                       VAR NumofStations : CARDINAL;
                      VAR CurrentStation : StationPtr );

(* Menu-driven station management.  Calls SelectStation *)

VAR

  AtStation     : StationPtr;
  StationCount,
  StationSelect : CARDINAL;
  Key           : CHAR;
  Escape        : BOOLEAN;

BEGIN

  (* Draw the window *)
  SetPlane( {2} );
  SetFunc( or, 0 );
  FillArea( 216, 28, 208, 228, CARDINAL(0FFFFH) );
  SetPlane( {3} );
  SetWindow( 216, 28, 208, 224 );

  GotoXY( 0, 0 );
  WrStr( '════════ STATIONS ════════' );
  WrStr( 'NAME     PHONE            ' );
  GotoXY( 0, 182 );
  WrStr( '══════════════════════════' );
  WrStr( '   ENTER·Select Station   ' );
  WrStr( '    F1·Add   F2·Delete    ' );

  FirstStation := StationList;
  StationSelect := 1;
  LOOP

      SetWindow( 216, 56, 208, 140);
      SetPlane( {3} );
      SetFunc( clr, 0 );
      GotoXY( 8, 140 );
      IF NumofStations = 0 THEN

          WrStr( 'No Stations. ' );

      ELSIF NumofStations = 1 THEN

          WrStr( '1 Station. ' );

      ELSE

          WrCard( NumofStations,1 );
          WrStr( ' Stations. ' );

      END (* IF *);

      Select( 216, 56, 424, 196, WriteStationEntry,
          NumofStations, StationSelect, Key, Escape );

      IF Escape & ( Key = ExtendKey.F1 ) THEN

          AddStation( StationList, NumofStations );

      ELSIF Escape & ( Key = ExtendKey.F2 ) & ( StationSelect > 0 ) THEN

          DelStation( StationList, StationSelect, NumofStations );

      ELSIF ~ Escape & ( Key = ASCII.esc ) THEN

          StationSelect := NumofStations + 1;
          EXIT;

      ELSIF ~ Escape & ( Key = ASCII.cr ) THEN

          EXIT;

      END (* IF *);

      SetPlane( {3} );
      SetFunc( clr, 0 );
      FillArea( 216, 56, 208, 158, CARDINAL(0) );

  END (* LOOP *);

  AtStation := StationList;
  StationCount := 1;

  WHILE ( AtStation # NIL ) & ( StationCount < StationSelect ) DO

      AtStation := AtStation^.Next;
      INC( StationCount );

  END (* WHILE *);


  SetPlane( {2,3} );
  SetFunc( clr, 0 );
  FillArea( 216, 28, 208, 228, CARDINAL(0) );
  SetWindow( 0, 0, 639, 349 );

  IF AtStation # NIL THEN

      SelectStation( AtStation^ );
      CurrentStation := AtStation;

  END (* IF *);

  SetPlane( {0,1,2,3} );
  ClearScreen;
  Redraw;

END StationMenu;

