        for (i = getOutput()->getHist()->getNumBins()-1; i >= 0; i--) {
       	    histDiff += FABS(getOutput()->getHist()->getAt(i) - 
       	    	exemp->getOutput()->getHist()->getAt(i));
            lambda->setAt(i, lambda->getAt(i) + 
                ZETA*(getOutput()->getHist()->getAt(i) - 
                exemp->getOutput()->getHist()->getAt(i)));
        }
