PROCEDURE EditAccount;
Edits account details in a screen-based interface, updating fields like number, name, address, city, and phone. Uses keyboard input and screen highlighting for field navigation and data entry.
Calls: 2 in UIUTIL (EnterCell, ReadKbd), 2 in UTILITY (HiLiteCell, LoLiteCell), 1 in Accounts_Payable (SaveAccount) and 1 in UTILITY2 (ReadKbd)
Called by: 1 in this module (MainMenu)

PROCEDURE EditAccount;
VAR
  AtField : integer;
BEGIN
  DrawAccount;
  Window(1,1,80,25);
  AtField:=1;
  with Account[CurrentAccount] do
    repeat
      case AtField of
        1 : HiLiteCell(19,2,4);
        2 : HiLiteCell(4,3,40);
        3 : HiLiteCell(4,4,40);
        4 : HiLiteCell(4,5,30);
        5 : HiLiteCell(35,5,15);
      end; (* case *)
      ReadKbd;
      case AtField of
        1 : LoLiteCell(19,2,4);
        2 : LoLiteCell(4,3,40);
        3 : LoLiteCell(4,4,40);
        4 : LoLiteCell(4,5,30);
        5 : LoLiteCell(35,5,15);
      end; (* case *)
      if escape then
        case Key of
          'P' : if AtField<5 then AtField:=AtField+1;
          'H' : if AtField>1 then AtField:=AtField-1;
        end
      else
        case Key of
          ^M  : if AtField<6 then AtField:=AtField+1;
          else begin
            case AtField of
              1 : begin
                    StrA:=EnterCell(19,2,4,['0'..'9',' ']);
                    Val(StrA,Number,I);
                  end;
              2 : Name:=EnterCell(4,3,40,[' '..'~']);
              3 : Address:=EnterCell(4,4,40,[' '..'~']);
              4 : City:=EnterCell(4,5,30,[' '..'~']);
              5 : Phone:=EnterCell(35,5,15,[' '..'~']);
            end; (* case *)
            DrawAccount;
            Window(1,1,80,25);
            AtField:=AtField+1;
          end;
        end; (* case *)
    until (AtField>5) or (Key=#27);
  SaveAccount;
end; (* EditAccount *)

