                case atField of
                    1  : LoLiteCell(19, 2, 4);
                    2  : LoLiteCell(4, 3, 40);
                    3  : LoLiteCell(4, 4, 40);
                    4  : LoLiteCell(4, 5, 30);
                    5  : LoLiteCell(39, 5, 15);
                end (* case *);
                if escFlag then begin
                    case key of
                        KEY_RT, KEY_DN  : if (atField < 5) then
                            atField := atField+1;
                        KEY_LT, KEY_UP, KEY_BACKTAB  : if (atField > 1) then
                            atField := atField-1;
                    end (* case *);
                end else begin
                    case key of
                        KEY_ENTER  : if (atField < 6) then
                            atField := atField + 1;
                        KEY_TAB  : if (atField < 5) then
                            atField := atField + 1;
                        ' '..'~'  : begin
                            case atField of
                                1  : if (key in ['0'..'9']) then begin
