    WriteKeyLine;
    REPEAT
      ReadKbd;
      CASE Key of
        'e' : IF ChangeStatus THEN BEGIN
                EditDelivery;
                WriteKeyLine;
              END;
        'p' : BEGIN
                PrintWind;
                WriteKeyLine;
              END;
      END;
    UNTIL Key=#27;
    IF DeliveryChanged THEN SaveDelivery;
    DrawLog;
  END;

SSM / FIDELIV / LoadDelivery (Turbo Pascal procedure)
PROCEDURE LoadDelivery;
Loads delivery record from DELIV.DAT file into memory structure, positioned according to log pointer value, or clears record if pointer is zero. Works with delivery data file and log tracking structure.
Calls: 1 in UTILITY2 (CheckFile)
Called by: 2 in this module (EditDelivery, EnterDelivery)

PROCEDURE LoadDelivery;

  BEGIN
    CheckFile('DELIV.DAT');
    ReSet(DeliveryFile);
    IF Log[CurrentLog].Pointer[Deliveryt]>0 THEN BEGIN
      Seek(DeliveryFile,Log[CurrentLog].Pointer[Deliveryt]-1);
      Read(DeliveryFile,Delivery);
    END
    ELSE FillChar(Delivery,SizeOf(Delivery),0);
    Close(DeliveryFile);
  END;

SSM / FIDELIV / SaveDelivery (Turbo Pascal procedure)
PROCEDURE SaveDelivery;
Saves delivery record to DELIV.DAT file, updating log pointer. Works with delivery data structure and log management system.
Calls: 1 in DREDIT (SaveLog), 1 in FIMENU (SaveLog) and 1 in UTILITY2 (CheckFile)
Called by: 1 in this module (EnterDelivery)

PROCEDURE SaveDelivery;

  BEGIN
    CheckFile('DELIV.DAT');
    ReSet(DeliveryFile);
    IF Log[CurrentLog].Pointer[Deliveryt]=0 THEN Log[CurrentLog].Pointer[Deliveryt]:=FileSize(DeliveryFile)+1;
    IF Log[CurrentLog].Pointer[Deliveryt]<0 THEN Log[CurrentLog].Pointer[Deliveryt]:=-Log[CurrentLog].Pointer[Deliveryt];
    Seek(DeliveryFile,Log[CurrentLog].Pointer[Deliveryt]-1);
    Write(DeliveryFile,Delivery);
    Close(TRFile);
    SaveLog(CurrentLog);
  END;

SSM / FIDELIV / Stick (Turbo Pascal function)
FUNCTION Stick(Inches : BYTE;ForFuel : fuel) : REAL;
Looks up fuel chart values by inches and fuel type, returning -1 for invalid inch values. Works with internal Chart data structure containing fuel delivery measurements.
Called by: 1 in this module (WriteDeliveryRow)

FUNCTION Stick(Inches : BYTE;ForFuel : fuel) : REAL;

  BEGIN
