PROCEDURE LoadLog;

  BEGIN
    ReSet(LogFile);
    IF (IOResult = $01) THEN
      ErrorMsg('FIM Data not found');
    Seek(LogFile,0);
    LastLog:=FileSize(LogFile)-1;
    IF LastLog>=0 THEN
      FOR I:=0 to LastLog DO Read(LogFile,Log[I]);
    SavetoLog:=LastLog+1;
    Close(LogFile);
    IF (IOResult = $FF) THEN
      ErrorMsg('FIM Data not found');
  END;

