SSM / FIMMP / CalcMMP (Turbo Pascal procedure)
PROCEDURE CalcMMP;
Calculates MMP (Monthly Management Payment) amounts based on current and previous readings, applies pricing and credit card fees to generate total charges. Works with internal data structures containing readings and pricing information.
Called by: 2 in this module (EditMMP, LoadMMP)

PROCEDURE CalcMMP;

  BEGIN
    WITH MMP DO BEGIN
      SubTotal[1]:=TR.Readings[1]+TR.Readings[5];
      SubTotal[2]:=TR.Readings[2]+TR.Readings[4];
      SubTotal[3]:=TR.Readings[3];
      SubTotal[4]:=TR.Readings[6]+TR.Readings[10];
      SubTotal[5]:=TR.Readings[7]+TR.Readings[9];
      SubTotal[6]:=TR.Readings[8];
      Previous[1]:=AuxTR.Readings[1]+AuxTR.Readings[5];
      Previous[2]:=AuxTR.Readings[2]+AuxTR.Readings[4];
      Previous[3]:=AuxTR.Readings[3];
      Previous[4]:=AuxTR.Readings[6]+AuxTR.Readings[10];
      Previous[5]:=AuxTR.Readings[7]+AuxTR.Readings[9];
      Previous[6]:=AuxTR.Readings[8];
      TotalAmount:=0;
      FOR I:=1 TO 6 DO BEGIN
        WithDrawn[I]:=SubTotal[I]-Previous[I];
        Amount[I]:=WithDrawn[I]*Price.Total[I]/10;
        TotalAmount:=TotalAmount+Amount[I];
      END; (* FOR *)
      CCFee:=CreditCard*Price.CardFee;
      SubTotalFee:=TotalAmount+CCFee;
      Total:=SubTotalFee-CreditCard;
    END;
  END;

SSM / FIMMP / EditMMP (Turbo Pascal procedure)
PROCEDURE EditMMP;
Edits MMP record fields for credit card and check number; updates related data structures and displays changes on screen.
Calls: 3 in FIMENU (SaveLog, WriteEditLine, WriteKeyLine), 3 in this module (CalcMMP, LoadMMP, WriteMMP), 2 in UIUTIL (EnterCell, ReadKbd), 2 in UTILITY (HiLiteCell, LoLiteCell), 2 in UTILITY2 (GotoLine, ReadKbd) and 1 in DREDIT (SaveLog)
Called by: 1 in this module (EnterMMP)

PROCEDURE EditMMP;

  VAR XPos,YPos,Size : INTEGER;
  BEGIN
    MMPChanged:=FALSE;
    GotoLine(34);
    WriteEditLine(MMPt);
    REPEAT
      CASE K of
        1     : BEGIN
                  XPos:=68; YPos:=50; Size:=10;
                END;
        2     : BEGIN
                  XPos:=3; YPos:=55; Size:=20;
                END;
      END;
      HiLiteCell(XPos,YPos-33,Size-1);
      ReadKbd;
      LoLiteCell(XPos,YPos-33,Size-1);
      CASE Key of
        #75,#72  : IF K>1 THEN K:=K-1;
        #77,#80  : IF K<2 THEN K:=K+1;
        'r'      : IF Log[CurrentLog].Pointer[MMPt]<0 THEN BEGIN
                     Log[CurrentLog].Pointer[MMPt]:=-Log[CurrentLog].Pointer[MMPt];
                     LoadMMP;
                     WriteMMP;
                     SaveLog(CurrentLog);
                     WriteEditLine(MMPt);
                     K:=1;
                   END;
        'd'      : IF Log[CurrentLog].Pointer[MMPt]>0 THEN BEGIN
                     Log[CurrentLog].Pointer[MMPt]:=-Log[CurrentLog].Pointer[MMPt];
                     SaveLog(CurrentLog);
                     Key:=#27;
                     Exit;
                   END;
        '0'..'9','.',' ' : BEGIN
                     MMPChanged:=TRUE;
                     CASE K of
                       1 : BEGIN
                             Val(EnterCell(XPos,YPos-33,Size-1,
                                 ['0'..'9','.',' ']),X,I);
                             MMP.CreditCard:=X;
                             CalcMMP; WriteMMP;
                           END;
                       2 : BEGIN
                             MMP.CheckNum:=
                               EnterCell(XPos,YPos-33,Size-1,['0'..'9','A'..'Z',' ']);
                           END;
                     END;
                   END;
      END;
      IF Key=#13 THEN IF K<2 THEN K:=K+1 ELSE Key:=#27;
    UNTIL Key=#27;
    Key:=#0;
    WriteKeyLine;
  END;

