SSM / FIMMP / LoadMMP (Turbo Pascal procedure)
PROCEDURE LoadMMP;
Loads MMP and Price data from files using log pointers; updates screen display via CalcMMP.
Calls: 2 in FITR (EnterTR, LoadTR), 1 in FIMENU (EnterTR) and 1 in this module (CalcMMP)
Called by: 3 in this module (EditMMP, EnterMMP, ViewMMPSummary)

PROCEDURE LoadMMP;

  VAR I : INTEGER;

  BEGIN
    ReSet(MMPFile);
    I:=CurrentLog-1;
    WHILE (Log[I].Pointer[MMPt]<=0) AND (I>=0) DO I:=I-1;
    LoadTR(I);
    IF Log[CurrentLog].Pointer[TRt]<=0 THEN EnterTR;
    IF Log[CurrentLog].Pointer[MMPt]>0 THEN BEGIN
      Seek(MMPFile,Log[CurrentLog].Pointer[MMPt]-1);
      Read(MMPFile,MMPS);
    END
    ELSE FillChar(MMP,SizeOf(MMP),0);
    Close(MMPFile);
    ReSet(PriceFile);
    I:=CurrentLog-1;
    WHILE (Log[I].Pointer[Pricet]<=0) AND (I>=0) DO I:=I-1;
    IF I>=0 THEN BEGIN
      Seek(PriceFile,Log[I].Pointer[Pricet]-1);
      Read(PriceFile,Price);
    END
    ELSE BEGIN
      IF Log[CurrentLog].Pointer[Pricet]>0 THEN BEGIN
        Seek(PriceFile,Log[CurrentLog].Pointer[Pricet]-1);
        Read(PriceFile,Price);
      END
      ELSE BEGIN
        FillChar(Price,SizeOf(Price),0);
      END;
    END;
    Close(PriceFile);
    CalcMMP;
  END;

