SSM / IAEDIT / EditEdit (Turbo Pascal procedure)
procedure EditEdit;
ReTotal
Calls: 3 in UTILITY2 (GotoLine, Message, ReadKbd), 2 in this module (Edit, ReTotal), 2 in UIUTIL (EnterCell, ReadKbd), 2 in UTILITY (HiLiteCell, LoLiteCell) and 1 in DRFORM (EditEdit)
Called by: 1 in DREDIT (LoadDIR), 1 in DRFORM (EditEdit) and 1 in this module (Edit)

procedure EditEdit;
var     Place :   integer;
        YPos :   integer;
begin   Message('EDIT MODE: ESC = Exit');
        Place := 1;
        repeat
            YPos := 8 + Place*2;
            GotoLine(YPos-10);
            HiLiteCell(49, YPos, 16);
            ReadKbd;
            LoLiteCell(49, YPos, 16);
            case Key of
                KEY_UP :   if (Place > 1) then
                    Place := Place - 1;
                KEY_DN :   if (Place < NumberofAccounts) then
                    Place := Place + 1;
                '0'..'9','.' :   begin
                    Val(EnterCell(49, YPos, 16, ['0'..'9','.']),
                        X, I);
                    if not DecPoint then
                        X := X / 100;
                    ReTotal(Descriptor[Place].Number, X);
                    DIRChanged := true;
                end;
            end (* case *);
            if (Key = #13) then
                Place := Place+1;
        until (Key = KEY_ESC) or (Place > NumberofAccounts);
        Key := #0;
        Message('E = Edit  P = Print  ESC = Exit');
end (* EditEdit *);

