PROCEDURE EditAddress;
VAR
  AtField : integer;
BEGIN
(*  DrawAddress; *)
  Window(1,1,80,25);
  AtField:=1;
  with Address[CurrentAddress] do
    repeat
      case AtField of
        1 : HiLiteCell(8,8,40);
