PROCEDURE WriteNode(ForNode : NodePtr) : NodePtr;
VAR
  Temp  : NodePtr;
  Count : CARDINAL;
BEGIN
  WITH ForNode^ DO
    IF ForNode<>NIL THEN
      CASE Type OF
        Symbol :
          WriteString(PName); |
        String :
          WriteString(StrV); |
        Integer :
          WriteInt(IntV,0); |
        List :
          Write('(');
          Count:=0;
          WHILE Elem[Count]<>NIL DO
            Write(' ');
            Temp:=WriteNode(Elem[Count]);
            Write(' ');
            INC(Count);
          END; (* WHILE *)
          Write(')');
        ELSE WriteString('INVALID NODE');
      END; (* CASE *)
    ELSE
      WriteString('nil');
    END; (* IF *)
  END; (* WITH *)
  WriteLn;
  RETURN ForNode;
END WriteNode;

