SSM / TransferAccounts / DirEntry (Turbo Pascal function)
FUNCTION DirEntry : LineType;
Reads directory entry from DTA buffer, constructs filename, and processes account data file by resetting balances. Works with file I/O and account records.
Calls: 2 in UTILITY2 (SetDir, SetDTA) and 1 in UTILITY (DirEntry)
Called by: 1 in Accounts_Payable (LoadAccounts), 1 in Mailing_Labels (UpdateAccount) and 1 in UTILITY (DirEntry)

FUNCTION DirEntry : LineType;

  VAR
    Line : LineType;
    I    : Integer;
  BEGIN
    Line:=''; I:=29;
    REPEAT
      Line:=Line+Chr(DTA[I]);
      I:=I+1;
    UNTIL DTA[I]=0;
    DirEntry:=Line;
    WITH Registers DO BEGIN
      AH:= $4F;
      CX:= Option;
      MSDos( Registers );
      ErrorFlag:=(Flags AND $01)<>0;
      IF ErrorFlag THEN ErrorNumber:= AL;
    END;
  END;

Type
  AccountRec     = record
    Number       :   integer;
    Name         :   string[40];
    Address      :   string[40];
    City         :   string[30];
    Phone        :   string[15];
    Balance      :   real;
    GT30         :   real;
    GT60         :   real;
  end;

Var
  Account     : AccountRec;
  AccountFile : File of AccountRec;
  Line        : LineType;

Begin
  SetDTA(DTA);
  Mask:='ACC????.DAT'+#0;
  SetDir($00);
  While Not ErrorFlag do begin
    Line := DirEntry;
    Line:=Copy(Line,2,255);
    WriteLn('EMPTYING FILE : ',Line);
    Assign(AccountFile,Line);
    ReSet(AccountFile);
    Read(AccountFile,Account);
    Close(AccountFile);
    ReWrite(AccountFile);
    Account.Balance:=0.0;
    Account.GT30:=0.0;
    Account.GT60:=0.0;
    Write(AccountFile, Account);
    Close(AccountFile);
  End;
End.
