SSM / VIEW / CMainWindow::OnCreate (C++ method)
int CMainWindow::OnCreate( LPCREATESTRUCT )
Queries the current text metrics to determine char size.
Calls: 2 in this module (CMainWindow, OnClose) and 1 in DATABASE (Defines the behaviors for the CDataBase class.: Terminate)
Called by: 1 in MAINFRM (implementation of the CMainFrame class: OnCreate) and 1 in this module (OnAbout)

int CMainWindow::OnCreate( LPCREATESTRUCT )
{
	TEXTMETRIC tm;

	// Get the text metrics.
	CDC* dc = GetDC();
	dc->GetTextMetrics( &tm );
	ReleaseDC( dc );

	// Decide the statistics on how many rows, etc., we can display.
	m_cxChar = tm.tmAveCharWidth;
	m_cxCaps = ( (tm.tmPitchAndFamily & 1 )? 3 : 2 ) * m_cxChar / 2;
	m_cyChar = tm.tmHeight + tm.tmExternalLeading;
	m_nMaxWidth = ( SIZENAME + SIZEPHONE + 1 ) * m_cxCaps;
	m_nVscrollPos = m_nHscrollPos = 0;

	return 0;
}

