TURING / turing / TuringMachine::getSymbol (C++ method)
char TuringMachine::getSymbol(int *at) {
Returns symbol from tape at given position, extending tape dynamically as needed. Works with internal tape data structure, handles negative and out-of-bounds indices.
Called by: 2 in this module (setSymbol, step)

char TuringMachine::getSymbol(int *at) {
	while (*at < 0) {
		char *newTape = new char[len + 1];
		newTape[0] = '\0';
		memcpy(newTape + 1, tape, len);    len++;
		if (tape) delete tape;             pos++;
		tape = newTape;	   				   (*at)++;
	}	
	while (*at >= len) {
		char *newTape = new char[len + 1];
		memcpy(newTape, tape, len);
		newTape[len] = '\0';               len++;
		if (tape) delete tape;
		tape = newTape;
	}                              return tape[*at]; 
}

