TURING / turing / TuringMachine::step (C++ method)
int TuringMachine::step() {
Advances the Turing machine by one step using the state table, modifying tape symbol and position based on current state and input symbol.
Calls: 2 in this module (getSymbol, setSymbol)
Called by: 1 in this module (main)

int TuringMachine::step() {
	char currChar = getSymbol(&pos);
	assert(state >= 0 && state < NUM_STATES);
	StateEntry currState = &stateTable[state][currChar];
	setSymbol(&pos, currState->writeSymbol);
	switch (currState->op) {
		case L : pos--; break;
		case R : pos++; break;
		case H :                   return FALSE;
		default : break;
	}
	state = currState->nextState;  return TRUE;
}

char initTape[] = {1, 1, 1};

StateEntryRec stateTable[][NUM_SYMBOLS] = {
	{ {1, R, 1}, {0, R, 0} },
	{ {0, R, 2}, {1, R, 1} },
	{ {0, R, 3}, {1, R, 3} },
	{ {0, H, 4}, {1, R, 4} }
};

