PROCEDURE CountSym;
Counts consecutive identical symbols around current tape position, displays count at cursor, waits for keypress before clearing display. Works with tape data structure and screen output.
Called by: 1 in this module (EditTape)

PROCEDURE CountSym;

  VAR
    TempPos        : 1..TapeLength;
    Count          : integer;

  BEGIN
    TempPos:=CarriagePosition-1;
    while Tape[TempPos]=Tape[CarriagePosition] do TempPos:=TempPos-1;
    Count:=CarriagePosition-TempPos;
    TempPos:=CarriagePosition+1;
    while Tape[TempPos]=Tape[CarriagePosition] do TempPos:=TempPos+1;
    Count:=Count+TempPos-CarriagePosition-1;
    GotoXY(CarriagePosition-LeftPosition+1,6);
    Write(Count);
    repeat until KeyPressed;
    GotoXY(CarriagePosition-LeftPosition+1,6);
    Write('   ');
  END;

