PROCEDURE Edit;

  BEGIN
    Key:=#0; EditMachine;
    REPEAT
      ReadKbd;
      CASE Key of
        'g'      : BEGIN
                     CurrentState:=FirstState;
                     RunMachine;
                   END;
        'c'      : RunMachine;
        't'      : BEGIN
                     EditFlag:=FALSE;
                     WriteInstruct(CurrentState,CurrentSymbol);
                     Key:=#0;
                     EditTape;
                   END;
        'm'      : BEGIN
                     EditFlag:=TRUE;
                     GotoXY(CarriagePosition-LeftPosition+1,5);
                     Write('^');
                     Key:=#0;
                     EditMachine;
                   END;
        'f'      : BEGIN
                     Key:=#0;
                     EditCell(71,10,5);
                     Val(Cell,I,J);
                     FirstState:=I;
                     GotoXY(71,10);Write(FirstState:5);
                   END;
        'd'      : BEGIN
                     Key:=#0;
                     EditCell(71,8,5);
                     Val(Cell,I,J);
                     DelayTime:=I;
                     GotoXY(71,8);Write(DelayTime:5);
                   END;
        'r'      : IF Trace THEN BEGIN
                     Trace:=FALSE;
                     GotoXY(71,9);
                     Write('OFF':5);
                   END ELSE BEGIN
                     Trace:=TRUE;
                     GotoXY(71,9);
                     Write('ON':5);
                   END;
        'l'      : LoadMachine;
        's'      : SaveMachine;
        ELSE IF EditFlag THEN EditMachine ELSE EditTape;
      END;
    UNTIL Key=#27;
  END;

