void Eevorg::drawAt(CDC* pDC, int atX, int atY, int hgt)
{   
	if (hgt < 2)
		return;

	CByteArray *curGen;
	int c, at;
	for (int n = 0; n < hgt;)
	{ 
		ASSERT(n < gen.GetSize());
		curGen = getGen(n);
		for (int m = curGen->GetSize()-1; m > 0; m--)
