	// retrieve the window rectangle
	CRect rectWnd;
	GetWindowRect(&rectWnd);

	// get the parent window and transform to its coordinates
	CSpaceView *pSpaceView = (CSpaceView *)GetParent();
	pSpaceView->ScreenToClient(&rectWnd);

