		ASSERT_VALID(item);

		SetSelection(item);    
		item->InvalidateItem();
	}
	CATCH(CException, e) {
		if (item != NULL) {
			ASSERT_VALID(item);
			item->Delete();
		}
		AfxMessageBox(IDP_FAILED_TO_CREATE);
	}
	END_CATCH

	EndWaitCursor();
