void  oView::drawLinks( CDC *pDC ) {
	oDocument *myDoc = GetDocument();
 	POSITION pos = myDoc->GetStartPosition();
	while (pos != NULL)	{
		oItem *anItem = (oItem *)myDoc->GetNextItem(pos);
		CPoint center = anItem->myRect.CenterPoint();
		POSITION pos2 = myDoc->GetStartPosition();
		while (pos2 != NULL) {
