int theWheelApp::Run() {
until a WM_QUIT message is received.
Calls: 6 in thewheel (ExitInstance, OnIdle, theWheelApp, ExitInstance, +2 more), 3 in wlFrameW (updateChildren, updateViews, wlFrameWnd), 1 in wlChildW (reset) and 1 in wlSpring (reset)
Called by: 3 in thewheel (DoDataExchange, DoDataExchange, DoDataExchange), 1 in MainFrm (implementation of the CMainFrame class: Dump) and 1 in SpaceView (PreCreateWindow)

int theWheelApp::Run() {

	ASSERT_VALID(this);

	BOOL bIdle = TRUE;
	LONG lIdleCount = 0;

	// get messages
	//     until a WM_QUIT message is received.
	for (;;) {

		// any work to be done?
		while (bIdle &&
			!::PeekMessage(&m_msgCur, 
						NULL, NULL, NULL, PM_NOREMOVE))
		{
			((wlFrameWnd *)m_pMainWnd)->
				updateChildren(m_msgCur.time, m_msgCur.pt);
			((wlFrameWnd *)m_pMainWnd)->
    			updateViews(m_msgCur.time);

			// call OnIdle while in bIdle state
			if (!OnIdle(lIdleCount++))
				bIdle = FALSE; // assume "no idle" state
		}

		// pump messages while available
		do {
			// pump message, but quit on WM_QUIT
			if (!PumpMessage())
				return ExitInstance();

			((wlFrameWnd *)m_pMainWnd)->
				updateChildren(m_msgCur.time, m_msgCur.pt);
			((wlFrameWnd *)m_pMainWnd)->
    			updateViews(m_msgCur.time);

			// reset "no idle" state after 
			//	  pumping "normal" message
			if (IsIdleMessage(&m_msgCur))
			{
				bIdle = TRUE;
				lIdleCount = 0;
			}

		} while (::PeekMessage(&m_msgCur, 
				NULL, NULL, NULL, PM_NOREMOVE));
	}

	ASSERT(FALSE);  // not reachable
}

