void branch(wlFrameView *theFrame, wlEevorg *parent, int iter) {
Creates branching child elements in a spreading activation network visualization, recursively building hierarchical structures from a parent node. Works with wlFrameView, wlEevorg, and wlChildView objects to generate nested visual representations.
Calls: 1 in wlchildv (wlChildView), 1 in wleevorg (wlEevorg) and 1 in wlframev (setChild)

void branch(wlFrameView *theFrame, wlEevorg *parent, int iter) {
		wlEevorg *leftChild = new wlEevorg(parent);
		theFrame->setChild(new wlChildView(leftChild));
		if (iter > 0)
				branch(theFrame, leftChild, iter - 1);
		wlEevorg *rightChild = new wlEevorg(parent);
		theFrame->setChild(new wlChildView(rightChild));
		if (iter > 0)
				branch(theFrame, rightChild, iter - 1);
}

