Called by: 1 in MainFrm (implementation of the CMainFrame class: Dump) and 1 in SpaceView (PreCreateWindow)

int theWheelApp::Run() {

		LONG sheepCount;

		do {
				sheepCount = 0;
				while (!::PeekMessage(&m_msgCur, NULL, NULL, NULL, PM_NOREMOVE) &&
								OnIdle(sheepCount++));

				if (m_msgCur.message == WM_MOUSEMOVE) { 
						sheepCount = 0; 
						while (OnIdle(sheepCount++));
				}
		} while (PumpMessage());

		return ExitInstance();
}

