		(int)width, (int)(3e-3*width*width+20.0), 
		SWP_NOZORDER | SWP_NOACTIVATE | SWP_NOREDRAW);	
	RedrawWindow(NULL,NULL, RDW_INVALIDATE | RDW_FRAME | RDW_NOERASE | RDW_UPDATENOW);

	parent->InvalidateRect(myRect, FALSE);
