void wlObject::grow() {
Grows a cellular automaton grid by one unit in each direction, applying transition rules based on neighboring cell sums. Works with internal char grid structure using getAt/setAt accessors.
Calls: 2 in wldoc (getAt, setAt)
Called by: 1 in thewheel (OnIdle)

void wlObject::grow() {
		if (rand() > RAND_MAX/girth)
				return;

		int newGirth = girth;
		int offset = newGirth/2+1;
		char *newBody = new char[newGirth*newGirth];
		for (int atx = -offset; atx <= offset; atx++)
				for (int aty = -offset; aty <= offset; aty++) {
						int dx, dy;
						int sum = 0;
						for (dx = -1; dx <= 1; dx++)
								for (dy = -1; dy <= 1; dy++)
										sum += (int)getAt(body, girth, atx+dx, aty+dy);
						setAt(&newBody, &newGirth, atx, aty, rules[sum]);
				}

		delete [] body;
		body = newBody;
		girth = newGirth;
}

