		if (mutFlag) {	// generate a single mutation
				int ruleNum = random(maxRule+1);
				ASSERT((ruleNum >= 0) && (ruleNum <= maxRule));
				int ruleVal;
				if (ruleNum > maxRule) {
						ruleVal = 0;
						maxRule = ruleNum;
				} 
				else {
