BOOL wlView::removeReferences( CMapPtrToPtr& viewList ) {
	POSITION pos = viewList.GetStartPosition();
	while (pos) {
		wlView *view;
		wlObject *object;
		viewList.GetNextAssoc( pos, (void *&)object, 
			(void *&)view );
